insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('1', 'IVA-001', 'No Real Market Need or Validation', 'Idea & Validation', 'external', 'The core failure mode of early-stage ventures is building solutions to problems that do not exist or are not painful enough to drive customer transaction behavior. CB Insights demonstrates that a lack of market need is the single largest cause of venture death, accounting for 42% of all cases. Founders often mistake their own enthusiasm for empirical demand, resulting in products nobody is willing to pay for.', '8', '10', '["Founder cannot name a single customer who has paid or committed to pay", "Product built entirely on founder assumptions without external validation", "Customer interviews only conducted with friends or family who gave positive feedback", "No evidence of repeat usage or willingness to pay from any user", "Founder responds to challenge with ''the market will catch up'' or ''people just do not understand it yet''"]', '2', 'Market Demand', '["IVA-003", "IVA-007", "GTM-002"]', '2026-07-10 13:31:56.95582+00', '2026-08-03 03:26:48.023851+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('2', 'IVA-002', 'Overly Niche or Derivative Idea', 'Idea & Validation', 'external', 'Chasing marginal user segments or replicating existing competitors without defining a clear, differentiated value proposition limits scaling potential. When founders build for an undefined or highly restricted audience without running rigorous discovery, they restrict their market size before writing a single line of code.', '5', '8', '["Total addressable market is too small to build a viable business", "Product is a near-identical copy of an existing solution with no meaningful differentiation", "Founder cannot articulate why their solution is 10x better than existing alternatives", "No clear reason why a customer would switch from what they already use", "Value proposition is incremental improvement rather than meaningful transformation"]', '2', 'Idea Quality', '["IVA-001", "GTM-004"]', '2026-07-10 13:31:56.95582+00', '2026-08-03 03:26:48.070904+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('3', 'IVA-003', 'Lack of a Specific Target User', 'Target Customer & ICP', 'external', 'Operating with vague customer profiles or assuming that someone will eventually buy the product leads to highly unfocused engineering efforts. Without isolating a highly defined beachhead market, the startup positioning remains diluted and cannot gain initial traction.', '6', '9', '["Founder says everyone is our customer or anyone who needs X", "No specific customer persona with name, role, company size, or problem defined", "Marketing budget spread across multiple channels and audiences with no focus", "Product features built for too many different types of users simultaneously", "No beachhead market identified — trying to serve all segments at once"]', '2', 'Customer Definition', '["IVA-001", "GTM-002", "GTM-004", "TCI-001", "TCI-002", "TCI-011", "TCI-016", "SLX-051"]', '2026-07-10 13:31:56.95582+00', '2026-09-13 06:26:33.588767+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('4', 'IVA-004', 'Poor Problem Selection', 'Idea & Validation', 'external', 'Tackling problems that are intellectually interesting but lack urgency or financial impact prevents monetization. If a problem does not disrupt a user daily operations or cause severe financial pain, customers will not allocate a portion of their budget to resolve it.', '6', '9', '["Customers say they like the idea but never actually buy or sign up", "Problem is a nice to have rather than a must have", "No customer can quantify how much the problem costs them in time or money", "Users work around the problem easily without the founder solution", "Founder is solving a problem they personally find interesting but have not validated externally"]', '2', 'Problem Quality', '["IVA-001", "IVA-003"]', '2026-07-10 13:31:56.95582+00', '2026-08-03 03:26:47.463681+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('5', 'IVA-005', 'Failure to Pivot', 'Idea & Validation', 'external', 'Stubbornly clinging to the original business plan in the face of contradictory customer data, market shifts, and financial metrics represents a fatal leadership error. Successful validation requires extreme cognitive flexibility, allowing founders to shift their product strategy when the evidence demands it.', '7', '10', '["Founder dismisses negative customer feedback as they just do not understand it yet", "Product has not changed meaningfully despite months of poor traction", "Founder refuses to consider alternative customer segments or use cases", "Financial metrics are declining but the team continues the same strategy", "Team members privately believe a change is needed but cannot convince the founder"]', '2', 'Learning Agility', '["IVA-001", "IVA-006"]', '2026-07-10 13:31:56.95582+00', '2026-08-03 03:26:47.510079+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('6', 'IVA-006', 'Insufficient Customer Feedback Loop', 'Idea & Validation', 'external', 'Delaying product launches due to perfectionism, fear of user criticism, or anxiety about real-world interaction isolates the product team from necessary market feedback. Swift, iterative feedback is the only mechanism that validates whether a product solves the intended user problem.', '6', '9', '["Product has been in development for months or years without a real user testing it", "Founder says they will launch when it is ready without a defined definition of ready", "No structured process for collecting and acting on user feedback", "Product decisions made in internal team meetings with no external input", "Feature changes driven by founder intuition rather than user evidence"]', '2', 'Validation Process', '["IVA-005", "IVA-007", "PRD-002"]', '2026-07-10 13:31:56.95582+00', '2026-08-03 03:26:47.554806+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('7', 'IVA-007', 'Building Before Problem Framing', 'Idea & Validation', 'external', 'Initiating technical development without a clear, falsifiable problem statement or hypothesis leads to massive R&D waste. High-performing startups begin with an explicit definition of a painful problem rather than a technology looking for an application.', '7', '10', '["Founder built a product first and is now searching for a customer to use it", "No written problem statement exists that can be tested or disproved", "Technical complexity of the product far exceeds the complexity of the problem", "Founder describes their startup as a technology rather than a solution to a problem", "Team spent months on engineering before speaking to a single potential customer"]', '2', 'Validation Process', '["IVA-001", "IVA-006", "PRD-003"]', '2026-07-10 13:31:56.95582+00', '2026-08-03 03:26:47.600553+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('8', 'GTM-001', 'Confusing GTM with Marketing', 'Go-To-Market', 'external', 'Founders routinely treat GTM as mere promotional activities such as launching social ads or publishing content, while failing to define customer identification matrices, value propositions, pricing, and distribution dynamics. A functional GTM plan must integrate the entire value-delivery loop — not just top-of-funnel awareness activities.', '6', '9', '["Founder equates GTM with running paid ads or posting on social media", "No documented GTM plan that covers customer identification, channels, pricing, and sales motion", "Marketing activities produce awareness but zero conversion to paying customers", "Founder cannot explain how a lead becomes a customer in their specific business", "Spending on marketing without a defined ICP, value proposition, or sales process in place"]', '2', 'GTM Understanding', '["GTM-002", "GTM-004", "GTM-006", "GTM-028"]', '2026-07-10 13:31:56.95582+00', '2026-08-03 07:01:43.581466+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('9', 'GTM-002', 'Undefined ICP or Broad Targeting', 'Go-To-Market', 'external', 'Marketing to everyone instead of a specific, highly receptive niche results in a total dilution of marketing spend. This broad approach generates highly fragmented, noisy, and uninterpretable customer feedback, preventing the team from isolating actionable product insights.', '7', '10', '["Marketing budget spread across multiple audiences and channels with no clear priority", "Founder says their product is for everyone or for any business that needs X", "Customer feedback is contradictory and impossible to act on", "High spend on advertising with very low conversion to qualified leads", "No written ICP document specifying company size, role, industry, and pain trigger"]', '2', 'Customer Targeting', '["IVA-003", "GTM-001", "GTM-004"]', '2026-07-10 13:31:56.95582+00', '2026-08-03 03:26:47.646886+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('10', 'GTM-003', 'Wrong or Untested Channels', 'Go-To-Market', 'external', 'Startups frequently assume that an acquisition channel that worked on a small scale will scale indefinitely. Customer acquisition methods that secure the first ten customers almost always break or become highly unprofitable when scaled to acquire one thousand.', '6', '9', '["CAC is increasing as spend on a channel increases rather than decreasing with scale", "Channel that brought first 10 customers is producing zero results now", "Founder has not tested more than one or two channels experimentally", "No data on which channel produces the highest quality leads at lowest cost", "Marketing spend concentrated entirely on one platform with no diversification"]', '2', 'Channel Strategy', '["GTM-001", "GTM-002", "SAL-001", "GTM-028"]', '2026-07-10 13:31:56.95582+00', '2026-08-03 07:01:43.581466+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('11', 'GTM-004', 'Poor Positioning and Messaging', 'Go-To-Market', 'external', 'If sales copy and brand assets fail to explain exactly how the product solves a specific problem for a specific user, conversion rates collapse. Without clear positioning, even a highly motivated target audience will fail to understand the product utility and move on.', '6', '8', '["Website homepage does not clearly state who the product is for and what problem it solves", "Prospects frequently ask so what does it actually do after a demo or pitch", "Conversion rate from landing page visitor to signup or inquiry is below 2%", "Different team members describe the product completely differently to prospects", "Messaging focuses on features rather than the specific outcome the customer will experience"]', '2', 'Positioning', '["GTM-002", "IVA-003", "SAL-002", "GTM-028", "MEX-001"]', '2026-07-10 13:31:56.95582+00', '2026-08-03 17:41:02.962743+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('12', 'GTM-005', 'Neglecting Pricing Strategy', 'Go-To-Market', 'external', 'Setting prices through guesswork or delaying monetization decisions starves the venture of capital. Pricing too low undervalues the product and damages cash flows, while pricing too high scares away crucial early adopters. Both failures destroy the ability to build a sustainable business.', '6', '9', '["Pricing set by asking what do competitors charge without understanding own value", "Founder discounts heavily on every deal to close rather than defending value", "No pricing page or pricing model documented — negotiated ad hoc every time", "Gross margin is below industry benchmark due to underpricing", "Early customers paying very little create expectations that prevent price increases later"]', '3', 'Pricing', '["SAL-003", "GTM-004", "SAL-005"]', '2026-07-10 13:31:56.95582+00', '2026-08-03 03:26:48.251819+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('13', 'GTM-006', 'Ignoring the Sales Motion', 'Go-To-Market', 'external', 'Startups often suffer from a severe mismatch between how their target customer naturally buys and how the startup attempts to sell. Forcing an enterprise buyer to use a self-serve portal for a highly complex, security-sensitive software package will cause deal cycles to stall.', '6', '9', '["Enterprise deals sitting in pipeline for 6+ months with no movement", "Self-serve signup with no sales support for a product that requires complex onboarding", "Sales cycle does not match the customer procurement or budget cycle", "Founder selling directly to individual users when the real buyer is a procurement team", "No alignment between how the product is priced and how the customer prefers to buy"]', '2', 'Sales-GTM Alignment', '["GTM-002", "SAL-001", "SAL-002"]', '2026-07-10 13:31:56.95582+00', '2026-08-03 03:26:47.739894+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('14', 'GTM-007', 'Over-Focusing on Acquisition at the Expense of Retention', 'Go-To-Market', 'external', 'Chasing raw user sign-ups while completely ignoring customer retention, referral pathways, and upsell pipelines creates a leaky bucket phenomenon. If customer churn matches or exceeds acquisition, the startup cannot establish a repeatable business model regardless of marketing spend.', '7', '9', '["Monthly new customer additions equal or less than monthly customer losses", "Entire marketing budget allocated to acquisition with zero retention or loyalty budget", "NRR below 80% — losing more from existing customers than gaining", "No referral programme, upsell motion, or expansion revenue strategy exists", "Founder measures success only by new sign-ups and not by active retained users"]', '3', 'Growth Strategy', '["SAL-005", "GTM-005", "SAL-003"]', '2026-07-10 13:31:56.95582+00', '2026-08-03 03:26:50.941925+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('15', 'SAL-001', 'Weak Pipeline and No Deals', 'Sales & Revenue', 'external', 'A lack of structured sales processes and pipeline tracking tools leaves founders without visibility into where their revenue is generated. This empty pipeline is a direct downstream consequence of failing to define the target buyer or the specific sales motion.', '7', '10', '["Founder cannot name who is in their pipeline and what stage each deal is at", "No CRM or pipeline tracking system — deals tracked in a spreadsheet or founder head", "Zero qualified leads generated in the past 30 days", "Revenue entirely dependent on referrals or inbound with no outbound motion", "Sales conversations happening but none converting to proposals or closed deals"]', '3', 'Pipeline Management', '["GTM-002", "GTM-006", "SAL-002", "SLX-001"]', '2026-07-10 13:31:56.95582+00', '2026-08-03 12:57:57.176523+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('16', 'SAL-002', 'Inability to Close Deals', 'Sales & Revenue', 'external', 'Early-stage founders who are frequently product-focused or technical often lack the specialized skills required to run discovery, handle objections, tell emotional stories, and close negotiations. This is compounded by a total absence of sales feedback loops to analyze lost deals.', '7', '10', '["Meetings happening but conversion to paid customer is below 10%", "Founder gives product demos but loses deal at pricing or negotiation stage", "No systematic analysis of why deals are lost", "Founder avoids following up aggressively because it feels pushy", "Proposals sent but never followed up on — waiting for the prospect to respond"]', '3', 'Sales Execution', '["SAL-001", "GTM-004", "GTM-006", "SLX-001", "SLX-021"]', '2026-07-10 13:31:56.95582+00', '2026-08-03 15:56:22.025132+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('17', 'SAL-003', 'Pricing and Unit Economics Confusion', 'Sales & Revenue', 'external', 'Startups frequently collapse because they fail to maintain a healthy relationship between Lifetime Value and Customer Acquisition Cost. CB Insights notes that 18% of failures are driven directly by pricing flaws, high defaults, and unmonetized free users.', '7', '10', '["Founder cannot calculate LTV or CAC without external help", "LTV:CAC ratio below 1.0 — spending more to acquire than the customer generates", "Pricing set without a gross margin calculation", "Large free user base with no conversion pathway to paid", "Revenue growing but profitability declining — unit economics are negative at scale"]', '3', 'Unit Economics', '["GTM-005", "SAL-004", "OPS-004"]', '2026-07-10 13:31:56.95582+00', '2026-08-03 03:26:46.457511+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('18', 'SAL-004', 'No Clear Revenue Model', 'Sales & Revenue', 'external', 'Prioritizing raw user growth over a concrete strategy for capturing financial value drives 17% of venture failures. Without a path to monetization, ventures burn through capital by selling products for less than the cost of production.', '7', '10', '["Product has users but no paying customers and no defined monetization plan", "Founder says they will figure out monetization later", "Revenue model changes every few months without evidence to support the change", "No clarity on whether the business is subscription, transactional, marketplace, or services", "Business burning cash with no defined trigger point at which revenue begins"]', '3', 'Revenue Model', '["BMD-001", "BMD-002"]', '2026-07-10 13:31:56.95582+00', '2026-08-03 06:22:40.252151+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('19', 'SAL-005', 'Over-Discounting and High Customer Churn', 'Sales & Revenue', 'external', 'Slashing prices or offering heavily customized terms to close desperate deals erodes profit margins and inflates operational complexity. High customer churn quickly washes away the revenue gains of vanity metrics, making sustainable growth mathematically impossible.', '7', '9', '["Average selling price declining quarter on quarter despite growing revenue", "Monthly churn above 3% — losing more than a third of revenue base annually", "Different customers on wildly different pricing and contract terms creating operational chaos", "Customers leaving within first 90 days after poor onboarding experience", "Win rate only achieved by heavily discounting — standard pricing never accepted"]', '3', 'Revenue Quality', '["SAL-003", "GTM-007", "GTM-005", "SLX-031"]', '2026-07-10 13:31:56.95582+00', '2026-08-03 17:27:50.533887+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('20', 'TM-001', 'Co-founder Conflicts', 'Team & Leadership', 'external', 'Misalignment regarding equity distribution, operational authority, strategic vision, and company values represents a primary failure point. Avoiding difficult conversations during the early stages of a venture typically results in explosive disputes under operational stress.', '7', '10', '["Co-founders have not had explicit conversations about roles, equity, and decision rights", "Disagreements escalate into personal conflicts rather than resolved as business decisions", "One co-founder making decisions in areas the other believes they own", "Equity split agreed informally with no vesting schedule or buyback provisions", "Co-founders privately contradicting each other in conversations with team or investors"]', '5', 'Co-founder Dynamics', '["TM-002", "TM-005", "TM-003"]', '2026-07-10 13:31:56.95582+00', '2026-08-03 03:26:48.158574+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('21', 'TM-002', 'Wrong or Weak Team Composition', 'Team & Leadership', 'external', 'Startups routinely crumble because they lack the specific technical, commercial, or operational expertise required for the mission. CB Insights identifies team composition issues as the primary cause in 23% of company failures.', '7', '10', '["Founding team has no one with relevant domain expertise or prior startup experience", "Critical business functions — sales, engineering, operations — have no experienced lead", "Team is composed entirely of friends or former colleagues without complementary skills", "Investors or advisors have flagged team composition gaps in feedback", "Founder cannot name a team member who could lead the company if they stepped away"]', '5', 'Team Quality', '["TM-001", "TM-004", "TM-003"]', '2026-07-10 13:31:56.95582+00', '2026-08-03 03:26:47.836438+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('22', 'TM-003', 'Solo Founder or Lack of Co-founders', 'Team & Leadership', 'external', 'Single-founder ventures face severe operational bottlenecks and lack the psychological support systems required to survive the early stages of building. Solo founders are statistically far more prone to execution stalls, burnout, and decision paralysis.', '5', '8', '["Founder is building entirely alone with no technical, commercial, or operational co-founder", "All critical decisions made by one person with no structured sounding board", "Founder is handling product, sales, operations, and team management simultaneously", "Investor feedback repeatedly mentions team as a risk factor", "Founder reports feeling overwhelmed, isolated, and without accountability structures"]', '5', 'Team Structure', '["TM-001", "TM-002", "TM-005"]', '2026-07-10 13:31:56.95582+00', '2026-08-03 03:26:48.204885+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('23', 'TM-004', 'Poor Hiring Practices', 'Team & Leadership', 'external', 'Rushing to hire ahead of achieving product-market fit artificially inflates cash burn and operational complexity. Technical founders often lack the specialized skills required to source, evaluate, and manage high-quality non-technical talent.', '6', '9', '["Hiring people the founder personally likes rather than those with the right skills", "New hires added before there is enough structured work for them to do", "No structured hiring process — no job description, skills test, or structured interview", "High early attrition — people leaving within 6 months of joining", "Founder unable to evaluate candidates for roles outside their own expertise"]', '5', 'Hiring', '["TM-002", "TM-005", "OPS-001", "TM-025", "OPS-026", "TM-035", "OPS-051", "OPS-056"]', '2026-07-10 13:31:56.95582+00', '2026-08-06 05:07:10.918428+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('24', 'TM-005', 'Weak Governance or Oversight', 'Team & Leadership', 'external', 'Making critical strategic, financial, and legal decisions solo without the advice of an active board, mentors, or external advisors leads to extreme blind spots and unchecked spending. Some degree of corporate structure is necessary from day one.', '5', '8', '["No board, advisory board, or formal mentorship structure in place", "Major financial or legal decisions made without professional advice", "No cap table management or shareholder agreement reviewed by legal counsel", "Founder making unilateral decisions on strategy, compensation, and equity without oversight", "No documentation of key business decisions — everything in the founder head"]', '5', 'Governance', '["TM-001", "FND-006", "OPS-004"]', '2026-07-10 13:31:56.95582+00', '2026-08-03 03:26:50.75513+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('25', 'TM-006', 'Cultural and Communication Problems', 'Team & Leadership', 'external', 'Mismatched core values, fragmented communication channels, and a total lack of psychological safety prevent team members from raising red flags. This cultural breakdown delays execution and hides severe product and financial risks.', '5', '8', '["Team members withhold bad news from the founder for fear of negative reaction", "No regular team meetings, status updates, or shared visibility into priorities", "High tension between departments or co-founders that remains unresolved", "Key people leaving and citing culture or communication as the reason", "Founder unaware of execution problems until they become crises"]', '5', 'Culture', '["TM-001", "TM-004", "TM-005"]', '2026-07-10 13:31:56.95582+00', '2026-08-03 03:26:49.014113+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('26', 'FND-001', 'Raising Too Little Capital', 'Fundraising', 'external', 'Underestimating the capital required to reach the next validation milestone forces founders into a state of continuous fundraising. Running out of runway before achieving product-market fit is a direct consequence of underfunded development cycles.', '7', '10', '["Runway below 6 months with no clear path to next funding or profitability", "Founder spending significant time fundraising when they should be building", "Capital raised did not get the business to a meaningful milestone that de-risks the next raise", "Team size or product scope had to be cut mid-cycle due to insufficient capital", "Founder underestimated burn by more than 30% when planning the round"]', '6', 'Capital Planning', '["FND-002", "OPS-004", "FND-007", "FIN-006"]', '2026-07-10 13:31:56.95582+00', '2026-08-03 18:33:03.573116+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('27', 'FND-002', 'Raising Too Much Capital Too Early', 'Fundraising', 'external', 'Taking excessive venture capital before proving business model repeatability introduces severe scaling pressure. Once millions of dollars are injected, the operational clock begins ticking rapidly, reducing the startup agility to pivot.', '5', '8', '["Large team hired before product-market fit is established", "Investor pressure to scale before the business model is repeatable", "Burn rate dramatically exceeds what the business actually needs at current stage", "Founder feels unable to pivot because investors expect a specific growth trajectory", "Valuation expectations from round make future fundraising at a meaningful step-up very difficult"]', '6', 'Capital Planning', '["FND-001", "OPS-003", "TM-004"]', '2026-07-10 13:31:56.95582+00', '2026-08-03 03:26:49.059411+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('28', 'FND-003', 'Wrong Investor Fit', 'Fundraising', 'external', 'Accepting capital from venture capital firms or angel investors who do not understand the specific industry sector or early-stage development dynamics leads to strategic misalignment. This mismatch can cause destructive board-level conflicts.', '5', '8', '["Investors pushing the business in a direction that contradicts what the market data shows", "Investor applying metrics from a different industry that do not fit this business model", "Board meetings dominated by conflict rather than strategic guidance", "Founder feeling unable to make obvious business decisions because of investor resistance", "Investor has no relevant domain relationships, intros, or expertise to add beyond money"]', '6', 'Investor Selection', '["FND-004", "TM-005", "FND-001"]', '2026-07-10 13:31:56.95582+00', '2026-08-03 03:26:48.295869+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('29', 'FND-004', 'Poor Investor Management', 'Fundraising', 'external', 'Failing to balance investor input is highly damaging. While ignoring investors deprives the startup of strategic resources, caving entirely to their demands can result in a total loss of operational control and ultimate strategic drift.', '5', '8', '["Investor updates sent irregularly or only when things are going well", "Founder making major decisions without looping in key investors", "Founder changing strategy based entirely on investor opinion rather than market data", "Investors surprised by major developments because they were not kept informed", "Relationship with investors is transactional rather than strategic partnership"]', '6', 'Investor Relations', '["FND-003", "TM-005"]', '2026-07-10 13:31:56.95582+00', '2026-08-03 03:26:49.156096+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('30', 'FND-005', 'Weak Pitch and Story', 'Fundraising', 'external', 'An inability to clearly articulate the problem, the solution, the target market, and the operational traction in an inspiring manner leads to investor indifference. This is often characterized by disorganized pitch decks and a lack of key performance metrics.', '5', '8', '["Pitch deck does not clearly explain the problem, solution, market size, and business model in the first 5 slides", "Founder cannot articulate why now is the right time for this business to exist", "No compelling narrative that connects the problem to the founder unique insight", "Key metrics missing from the pitch — no revenue, no growth rate, no unit economics", "Investors consistently ask the same clarifying questions that the pitch should pre-answer"]', '6', 'Fundraising Execution', '["FND-001", "GTM-004"]', '2026-07-10 13:31:56.95582+00', '2026-08-03 03:26:49.106713+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('31', 'FND-006', 'Poor Fundraising Timing', 'Fundraising', 'external', 'Attempting to raise capital in highly depressed macroeconomic environments or seeking expansion capital with only an unvalidated prototype leads to rapid rejection. Founders must align their fundraising with clear funding cycles and meaningful milestones.', '5', '8', '["Approaching Series A investors with pre-revenue or minimal revenue traction", "Starting to fundraise with less than 3 months of runway remaining", "Raising in a market sector that investors have publicly deprioritized", "No clear milestone achieved that would justify the valuation being sought", "Investor meetings happening but no term sheets or meaningful interest after 50+ meetings"]', '6', 'Fundraising Strategy', '["FND-001", "FND-005"]', '2026-07-10 13:31:56.95582+00', '2026-08-03 03:26:46.968634+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('32', 'FND-007', 'Burning Cash During a Fundraise', 'Fundraising', 'external', 'Aggressively scaling administrative and marketing expenses while a funding round is still being negotiated introduces massive bankruptcy risk. If the funding round drags on or collapses, the startup quickly runs out of runway.', '7', '10', '["Burn rate increased significantly in anticipation of a round that has not closed", "New hires made or office space signed during active fundraise negotiations", "Less than 2 months of runway remaining with round still uncertain", "Founder spending on growth before the capital to fund that growth is confirmed", "Business becomes dependent on the round closing — no plan B if it falls through"]', '6', 'Capital Management', '["FND-001", "OPS-004", "FND-006", "FIN-006"]', '2026-07-10 13:31:56.95582+00', '2026-08-03 18:33:03.573116+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('33', 'PRD-001', 'Building Unwanted Features', 'Product', 'external', 'Assuming that adding more features will naturally make a product better represents a major cognitive trap. CB Insights attributes 17% of failures to user-unfriendly products, which are typically bloated with unvalidated, confusing functionality that increases complexity without increasing value.', '5', '8', '["Product has many features but users only actively use two or three of them", "New features launched without testing whether existing features are working", "Feature requests from one customer immediately added to the roadmap for everyone", "Product complexity is increasing but retention and engagement is not improving", "Team spending more time building new features than fixing existing experience gaps"]', '4', 'Build Discipline', '["PRD-002", "PRD-005", "IVA-006"]', '2026-07-10 13:31:56.95582+00', '2026-08-03 03:26:47.062279+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('34', 'PRD-002', 'Lack of User Feedback Loop', 'Product', 'external', 'Developing a product based on internal assumptions without continuous, data-driven feedback from early adopters results in solving the wrong problem. Bouncing ideas off actual users is the only way to validate product utility and ensure the team is building what the market actually needs.', '6', '9', '["Product decisions made in internal meetings without reference to user data or interviews", "No structured user research, usability testing, or customer interview programme", "Team does not know what percentage of users complete the core job to be done", "NPS or user satisfaction score never measured or not tracked regularly", "Founder has not spoken to a user about their experience in the last 30 days"]', '4', 'Feedback and Iteration', '["PRD-001", "IVA-006", "PRD-005"]', '2026-07-10 13:31:56.95582+00', '2026-08-03 03:26:49.201114+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('35', 'PRD-003', 'Over-Engineering and Perfectionism', 'Product', 'external', 'Delaying the launch of a product to achieve technical perfection destroys operational momentum. Slowness in launching is frequently a psychological defense mechanism designed to avoid external user judgment — treating not ready yet as protection against the risk of failure.', '5', '8', '["Product has been in development for more than 12 months without a user testing it", "Founder delays launch because this one feature needs to be perfect first", "Engineering team optimizing infrastructure and architecture before product is validated", "Technical complexity of the codebase far exceeds what the current problem requires", "Competitors have shipped and are getting feedback while this team is still building"]', '4', 'Build Discipline', '["PRD-001", "IVA-006", "IVA-007"]', '2026-07-10 13:31:56.95582+00', '2026-08-03 03:26:48.342669+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('36', 'PRD-004', 'Poor User Experience or Product Quality', 'Product', 'external', 'A slow, buggy, or highly complicated user interface alienates early adopters. If the core feature of the product does not function intuitively and reliably, user adoption will stall regardless of how strong the underlying idea is.', '6', '9', '["Users signing up but not completing onboarding or activating the core feature", "High support ticket volume for basic usability issues", "Users reporting bugs in core functionality that should have been caught in QA", "Page load times or app performance consistently generating user complaints", "Churning users cite difficult to use or too buggy as the reason for leaving"]', '4', 'Product Quality', '["PRD-002", "PRD-003", "SAL-005"]', '2026-07-10 13:31:56.95582+00', '2026-08-03 03:26:49.246921+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('37', 'PRD-005', 'No Clear Product Vision', 'Product', 'external', 'Adding random features reactively without a coherent roadmap causes teams to lose operational alignment and dilutes long-term customer value. A product without a clear vision becomes whatever the loudest customer or most recent investor requests.', '5', '8', '["Product roadmap changes significantly every quarter based on whatever comes up", "Team cannot articulate what the product will be in 12 months and why", "Features added for one enterprise customer making the product worse for all others", "No north star metric that the entire product team is optimising toward", "Product strategy described differently by the founder, product lead, and sales team"]', '4', 'Product Strategy', '["PRD-001", "PRD-002", "TM-006"]', '2026-07-10 13:31:56.95582+00', '2026-08-03 03:26:48.388349+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('38', 'PRD-006', 'Sacrificing User Needs for Quick Monetization', 'Product', 'external', 'Prioritizing revenue collection before validating product-market fit damages the core user experience. Solving the primary user problem must precede monetization, as chasing immediate revenue often results in a product that nobody loves and therefore cannot retain users or grow organically.', '5', '8', '["Revenue features — ads, upsells, paywalls — added before core product experience is strong", "User complaints about monetization model outweigh complaints about any other issue", "Engagement and retention metrics declining after monetization was introduced", "Product decisions consistently optimised for short-term revenue at expense of user value", "Negative reviews specifically calling out the monetization approach as aggressive or unfair"]', '4', 'Product Strategy', '["PRD-005", "SAL-003", "GTM-007"]', '2026-07-10 13:31:56.95582+00', '2026-08-03 03:26:48.486967+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('39', 'PRD-007', 'Product Mis-Timing', 'Product', 'external', 'Launching when the market is either completely unready — lacking infrastructure — or highly saturated with dominant competitors kills traction. CB Insights notes that incorrect market timing drives roughly 13% of startup failures.', '6', '9', '["Market infrastructure required for the product does not yet widely exist", "Product launched into a category already dominated by well-funded incumbents with strong network effects", "Early adopters interested but the mass market is not ready to change behaviour", "Regulatory environment blocking adoption that the founder did not anticipate", "Competitors launched 2-3 years earlier and have already captured the addressable market"]', '4', 'Market Timing', '["IVA-001", "IVA-004", "GTM-002"]', '2026-07-10 13:31:56.95582+00', '2026-08-03 03:26:51.034202+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('40', 'OPS-001', 'No Processes or Ad-Hoc Operations', 'Operations & Systems', 'external', 'Operating in a continuous state of firefighting without standard processes for sales, support, HR, and finance means every operational crisis is handled as a novel event. This prevents the organization from scaling because every problem requires the founder direct involvement to solve.', '5', '8', '["Same type of problem occurs repeatedly with no systematic fix implemented", "No documented SOPs for any core business function", "Founder is personally involved in resolving customer complaints or operational issues", "New team members have no structured way to learn how things work", "Quality of output is inconsistent because there is no defined standard"]', '4', 'Process Building', '["OPS-002", "OPS-003", "TM-006", "OPS-021", "OPS-031", "OPS-036"]', '2026-07-10 13:31:56.95582+00', '2026-08-06 04:47:50.02354+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('41', 'OPS-002', 'Founder Doing Everything — Failure to Delegate', 'Operations & Systems', 'external', 'A failure to delegate technical, administrative, and sales tasks creates severe operational bottlenecks. When the founder acts as the single point of failure, organizational momentum grinds to a halt and the business cannot grow beyond the founder personal bandwidth.', '6', '9', '["Founder working 80+ hours per week and still falling behind", "Team members waiting for founder approval before completing routine tasks", "Founder involved in customer calls, product decisions, hiring, and finance simultaneously", "Decisions that could be delegated are escalated to the founder because the team does not trust their own judgment", "Business growth stalled at the exact capacity the founder can personally manage"]', '4', 'Delegation', '["OPS-001", "TM-004", "SCL-004", "OPS-026", "OPS-051"]', '2026-07-10 13:31:56.95582+00', '2026-08-06 05:01:42.191734+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('42', 'OPS-003', 'Scaling Prematurely Without Operational Stability', 'Operations & Systems', 'external', 'Expanding hiring, infrastructure, or marketing before proving repeatable market demand burns capital rapidly. Operational processes must be stable before scaling is initiated — otherwise scaling amplifies existing problems rather than solving them.', '6', '9', '["Team doubled in size but output did not improve proportionally", "Marketing spend increased but CAC increased rather than decreased", "Infrastructure built for 100x scale when current usage is 10x", "Customer support volume grew faster than the team ability to handle it", "Scaling revealed that the core process did not actually work reliably at lower volumes either"]', '4', 'Scaling Readiness', '["OPS-001", "OPS-004", "FND-002"]', '2026-07-10 13:31:56.95582+00', '2026-08-03 03:26:51.171537+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('43', 'OPS-004', 'Financial Disorganization', 'Operations & Systems', 'external', 'Operating without structured budgeting, precise financial forecasting, or strict cash controls leads to sudden cash emergencies. Ignoring the burn rate is a primary driver of sudden venture bankruptcy because the cash crisis only becomes visible when it is already too late to fix.', '7', '10', '["Founder cannot state current runway in months without calculating it on the spot", "No monthly financial review process — P&L and cash position reviewed ad-hoc", "Spending decisions made without checking against a budget", "Unexpected tax or compliance bills arrived that the founder had not planned for", "Founder discovered they were running out of cash less than 60 days before it would happen"]', '4', 'Financial Management', '["OPS-003", "FND-001", "OPS-005", "FIN-001", "FIN-011", "FIN-026"]', '2026-07-10 13:31:56.95582+00', '2026-08-03 19:00:19.505767+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('44', 'OPS-005', 'Lack of Metrics or KPIs', 'Operations & Systems', 'external', 'Failing to track operational and financial metrics such as retention, CAC, LTV, and customer satisfaction leaves the executive team making decisions based on intuition rather than empirical data. Without measurement, problems are invisible until they become crises.', '5', '8', '["No defined KPIs for any team or function", "Founder makes strategic decisions based on gut feel with no supporting data", "No product analytics — founder does not know which features users actually use", "Revenue and growth reported in top-line numbers without cohort or retention analysis", "Problems discovered reactively when they become serious rather than caught early by trends"]', '4', 'Data and Measurement', '["OPS-004", "OPS-001", "SAL-003"]', '2026-07-10 13:31:56.95582+00', '2026-08-03 03:26:49.292936+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('45', 'OPS-006', 'Neglecting Compliance and Governance', 'Operations & Systems', 'external', 'Ignoring legal requirements, tax obligations, and regulatory frameworks can sink a startup. Unchecked spending and contractual oversights are typical consequences of neglecting basic operational oversight and treating compliance as someone else problem.', '6', '9', '["Operating without key licences, registrations, or regulatory approvals required by law", "No legal review of customer contracts, employment agreements, or vendor terms", "Tax filing delayed or missed — founder unaware of obligations", "GDPR, DPDP, or data privacy requirements ignored in product design", "Investor due diligence revealing legal or compliance gaps that delay or kill a round"]', '6', 'Regulatory Compliance', '["TM-005", "OPS-004"]', '2026-07-10 13:31:56.95582+00', '2026-08-03 03:26:51.127075+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('46', 'SCL-001', 'Organisational Complexity Outpacing Systems', 'Scaling & Operational Maturity', 'external', 'When a team grows from 10 to 100 people, the loose, informal way of doing things stops working. Decisions slow down, people are not sure who owns what, and mistakes start happening because nobody has clear end-to-end responsibility anymore.', '6', '9', '["Decisions that used to take one conversation now take weeks and multiple meetings", "Team members unclear about who has final authority on key decisions", "Same mistakes repeated across teams because there is no shared learning system", "Founder reports the company feels slow and bureaucratic compared to six months ago", "Significant duplicated effort between teams who are not communicating"]', '6', 'Operational Scaling', '["SCL-002", "SCL-004", "OPS-001"]', '2026-07-10 13:31:56.95582+00', '2026-08-03 03:26:49.3402+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('47', 'SCL-002', 'Core Processes Collapsing Under Growth', 'Scaling & Operational Maturity', 'external', 'Things the founder used to manage personally start falling apart once there is too much volume. Orders get missed, customers get a worse experience, and the team morale drops because nothing feels under control.', '6', '9', '["Customer complaints increasing proportionally faster than customer growth", "Orders, deliverables, or tasks getting missed that never used to get missed", "Team morale declining because operational chaos makes their jobs harder", "Founder plugging operational gaps personally instead of building systems", "Scaling exposed that the process that worked at small scale was never actually a real process"]', '6', 'Operational Scaling', '["SCL-001", "OPS-001", "SCL-008"]', '2026-07-10 13:31:56.95582+00', '2026-08-03 03:26:49.390185+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('48', 'SCL-003', 'No Documentation or Knowledge Management', 'Scaling & Operational Maturity', 'external', 'Knowledge about how things work lives only in the founder head or a few early employees. New people joining the team have to figure things out the hard way, which slows everyone down.', '4', '7', '["No documented SOPs, wikis, or process guides for any core function", "New hires take 3+ months to become productive because knowledge transfer is entirely informal", "If a key early employee left, the business would lose critical operational knowledge", "Same questions asked repeatedly by team members because answers are not written down", "Onboarding experience inconsistent — what a new hire learns depends on who they sit next to"]', '6', 'Operational Scaling', '["SCL-001", "OPS-001", "SCL-007"]', '2026-07-10 13:31:56.95582+00', '2026-08-03 03:26:49.437349+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('49', 'SCL-004', 'Founder Becoming the Organisational Bottleneck', 'Scaling & Operational Maturity', 'external', 'Without realising it, founders end up being the person everyone needs to route decisions through. Every decision requires their approval, which slows the whole company down.', '6', '9', '["Managers cannot make any meaningful decision without founder sign-off", "Teams waiting days for founder responses before they can proceed", "Founder calendar is full of internal decision meetings leaving no strategic time", "Growth of the business has plateaued at exactly the founder personal capacity", "Team has stopped taking initiative because they know the founder will override them"]', '6', 'Operational Scaling', '["OPS-002", "SCL-001", "SCL-011"]', '2026-07-10 13:31:56.95582+00', '2026-08-03 03:26:49.762976+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('50', 'SCL-005', 'Cross-Team Silos and Communication Breakdown', 'Scaling & Operational Maturity', 'external', 'As departments grow, they start working in their own bubble — using their own systems, their own language, and their own way of doing things. The casual conversations that used to keep everyone aligned no longer happen.', '5', '8', '["Product and sales making conflicting promises to customers independently", "Engineering building features that marketing is not even aware of launching", "Different teams using different tools with no integration or shared visibility", "Important decisions made in one team without informing affected teams until too late", "Significant duplicated work discovered between departments doing the same thing independently"]', '6', 'Operational Scaling', '["SCL-001", "TM-006", "SCL-006"]', '2026-07-10 13:31:56.95582+00', '2026-08-03 03:26:49.48271+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('51', 'SCL-006', 'Communication Systems Not Keeping Pace with Team Size', 'Scaling & Operational Maturity', 'external', 'What used to be a quick chat now needs proper systems — updates, meetings, dashboards. Founders often do not realise how much coordination is needed once the team grows.', '4', '7', '["Important updates communicated via informal chat messages that get buried", "Team members missing key context because information sharing is inconsistent", "No regular all-hands or team update cadence to share company direction", "Different parts of the team working from different assumptions about priorities", "Founder assumes team knows something that was never actually formally communicated"]', '6', 'Operational Scaling', '["SCL-005", "TM-006", "SCL-001"]', '2026-07-10 13:31:56.95582+00', '2026-08-03 03:26:49.815869+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('52', 'SCL-007', 'Inconsistent Onboarding and Knowledge Transfer', 'Scaling & Operational Maturity', 'external', 'Without a proper onboarding process, every new person picks up the job in their own way, often taught informally by whoever is around. This creates inconsistency across the team and uneven quality.', '4', '7', '["No structured onboarding programme — new hires figure it out as they go", "Time to productivity for new hires is more than 3 months across roles", "Quality of work varies significantly between team members doing the same function", "New hires frequently make mistakes that experienced staff know to avoid", "Onboarding experience depends entirely on which team member is most available to help"]', '6', 'Operational Scaling', '["SCL-003", "TM-004", "OPS-001", "TM-025"]', '2026-07-10 13:31:56.95582+00', '2026-08-03 19:03:36.943672+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('53', 'SCL-008', 'Quality Degradation at Scale', 'Scaling & Operational Maturity', 'external', 'When the founder could personally check every piece of work, quality stayed high. Once that is no longer possible and there is no formal quality management system, errors multiply.', '6', '9', '["Customer satisfaction scores declining as the team grows", "Quality issues discovered by customers before they are caught internally", "No formal QA process — quality depends on individual team members diligence", "Founder spending time fixing quality issues that should be caught before reaching them", "Inconsistent customer experience reported depending on which team member they interact with"]', '6', 'Operational Scaling', '["SCL-002", "OPS-001", "PRD-004"]', '2026-07-10 13:31:56.95582+00', '2026-08-03 03:26:49.862483+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('54', 'SCL-009', 'Management Layer Confusion and Role Ambiguity', 'Scaling & Operational Maturity', 'external', 'As the company grows, a whole new layer of managers and team leads appears. Founders struggle to decide how much responsibility each manager should have.', '5', '8', '["Newly promoted managers unclear about the extent of their decision-making authority", "Individual contributors bypassing their manager and escalating directly to the founder", "Managers spending more time in coordination meetings than doing actual work", "Accountability gaps — tasks falling between managers who each believe the other owns it", "Founder overriding manager decisions publicly, undermining their authority"]', '6', 'Operational Scaling', '["SCL-001", "SCL-004", "TM-006"]', '2026-07-10 13:31:56.95582+00', '2026-08-03 03:26:49.575053+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('55', 'SCL-010', 'Decision Velocity Declining with Growth', 'Scaling & Operational Maturity', 'external', 'What used to take five minutes can now take days because of approval chains and unclear processes. Founders often do not realise their company has outgrown quick, informal decision-making until it is already significantly slowing everyone down.', '5', '8', '["Routine decisions taking 3-5x longer than they used to", "Teams citing slow decision-making as a reason for missed deadlines", "Meetings called to make decisions that could be made by one person with clear authority", "Founder approving things they do not need to be approving", "Competitors shipping faster because their decision processes are leaner"]', '6', 'Operational Scaling', '["SCL-004", "SCL-009", "SCL-001"]', '2026-07-10 13:31:56.95582+00', '2026-08-03 03:26:49.907745+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('56', 'SCL-011', 'Founder Inability to Let Go of Control', 'Scaling & Operational Maturity', 'external', 'Many founders keep making decisions themselves or jumping into problems personally, even after hiring managers to do that job. This quietly tells the team that only the founder judgment is trusted.', '6', '9', '["Founder regularly overriding or redoing work that managers have already completed", "Managers deferring to the founder rather than exercising their own judgment", "Team has stopped bringing proposals because the founder typically changes everything anyway", "Founder calendar dominated by execution tasks rather than strategic leadership", "Managers leaving because they feel they are not actually given real responsibility"]', '6', 'Operational Scaling', '["SCL-004", "OPS-002", "SCL-009"]', '2026-07-10 13:31:56.95582+00', '2026-08-03 03:26:48.578113+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('57', 'SCL-012', 'Multiple Revenue Streams Creating Financial Complexity', 'Scaling & Operational Maturity', 'external', 'As a company grows, it often starts selling in different ways — subscriptions, one-time projects, different regions — each with its own pricing and billing rules. Managing all of this becomes confusing and cash flow harder to predict.', '5', '7', '["Finance team cannot produce a clean revenue breakdown by stream without significant manual work", "Different revenue streams using different billing systems that do not integrate", "Cash flow harder to predict because different streams have different payment timing", "No single view of total ARR, MRR, or revenue by customer across all streams", "Sales team offering different combinations of revenue streams causing contracting complexity"]', '6', 'Revenue Management at Scale', '["SCL-013", "OPS-004", "OPS-005", "FIN-026"]', '2026-07-10 13:31:56.95582+00', '2026-08-03 19:00:19.505767+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('58', 'SCL-013', 'Pricing Complexity at Scale', 'Scaling & Operational Maturity', 'external', 'A single simple price that worked early on no longer fits as the company starts serving very different types of customers. Founders often get this wrong — charging too little to win a deal, or too much and scaring customers away.', '5', '8', '["Large customer negotiations consistently resulting in custom pricing and non-standard terms", "Enterprise customers paying wildly different prices for equivalent value", "Pricing page outdated or missing entirely for the company current product suite", "Sales team constantly asking for pricing exceptions to close deals", "Discounting patterns inconsistent — some reps discount heavily, others not at all"]', '6', 'Revenue Management at Scale', '["GTM-005", "SAL-003", "SCL-012"]', '2026-07-10 13:31:56.95582+00', '2026-08-03 03:26:51.21818+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('59', 'SCL-014', 'Subscription Revenue Management Complexity', 'Scaling & Operational Maturity', 'external', 'Recurring revenue comes with the responsibility of forecasting renewals and managing churn. Founders who are used to one-time sales often are not prepared for the discipline that subscription tracking requires.', '5', '8', '["No renewal tracking system — renewals missed or handled reactively", "Churn discovered only when revenue drops rather than predicted in advance", "No health scoring for subscription customers — no early warning system", "Expansion and contraction revenue not tracked separately from new ARR", "Customer success team does not know which accounts are at risk of churning"]', '6', 'Revenue Management at Scale', '["SAL-005", "SCL-012", "OPS-005"]', '2026-07-10 13:31:56.95582+00', '2026-08-03 03:26:51.264819+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('60', 'SCL-015', 'Acquisition vs Retention Balance at Scale', 'Scaling & Operational Maturity', 'external', 'Growing companies need to balance bringing in new business while also keeping their existing customers happy. Most founders are not naturally good at balancing both simultaneously.', '5', '8', '["NRR below 100% — existing customer base shrinking in value despite new customer additions", "Customer success team underfunded relative to sales and marketing", "Churn acceleration as the company focuses entirely on new logo growth", "Long-term customers feeling neglected while all attention goes to new deals", "Growth targets met on new bookings but missed on net revenue due to churn"]', '6', 'Revenue Management at Scale', '["GTM-007", "SAL-005", "SCL-014"]', '2026-07-10 13:31:56.95582+00', '2026-08-03 03:26:49.621076+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('61', 'SCL-016', 'Revenue Forecasting Becoming Unreliable', 'Scaling & Operational Maturity', 'external', 'As the business grows, sales cycles get longer and less predictable, and founders often stay too optimistic. This leads to nasty surprises when targets are missed.', '5', '8', '["Quarterly revenue forecasts consistently off by more than 20%", "Pipeline coverage ratio not tracked — no idea how much pipeline is needed to hit target", "Sales team reporting deals as likely to close that take twice as long as expected", "Board and investors regularly surprised by revenue performance versus plan", "Financial planning assumptions based on early-stage growth rates that no longer apply"]', '6', 'Revenue Management at Scale', '["OPS-004", "OPS-005", "SAL-001"]', '2026-07-10 13:31:56.95582+00', '2026-08-03 03:26:47.106942+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('62', 'SCL-017', 'Spending Growing Faster Than Financial Controls', 'Scaling & Operational Maturity', 'external', 'As more money comes in, it is tempting to spend more. Founders often underestimate how quickly small mistakes in spending assumptions can snowball into a serious cash problem.', '6', '9', '["Headcount grew faster than revenue in the last two quarters", "No budget approval process — team members spending against loosely defined guidelines", "Monthly burn rate increasing without a corresponding improvement in key metrics", "Finance team only reporting on spend after it has happened rather than forecasting and flagging", "Runway shortening quarter on quarter without a deliberate decision to accelerate burn"]', '6', 'Revenue Management at Scale', '["OPS-004", "FND-001", "SCL-016", "FIN-016"]', '2026-07-10 13:31:56.95582+00', '2026-08-03 18:42:34.4852+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('63', 'SCL-018', 'Working Capital Trapped in Growth', 'Scaling & Operational Maturity', 'external', 'As companies grow, they often have to wait longer to get paid or carry more inventory. This ties up money that used to move quickly and founders can be caught off guard when expected cash does not arrive on time.', '6', '9', '["Accounts receivable growing faster than revenue — customers paying slower", "Inventory levels high relative to sales velocity for physical product businesses", "Cash position deteriorating even though the P&L looks healthy", "Founder surprised by inability to make payroll despite the business being profitable on paper", "Payment terms extended to enterprise customers creating a 90+ day cash cycle"]', '6', 'Revenue Management at Scale', '["OPS-004", "SCL-017", "FND-001", "FIN-001"]', '2026-07-10 13:31:56.95582+00', '2026-08-03 18:26:55.440486+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('64', 'SCL-019', 'Profit Margins Quietly Shrinking', 'Scaling & Operational Maturity', 'external', 'Supporting bigger customers or new markets often comes with new costs. Founders often do not notice their margins shrinking until it has already become a real problem for the business long-term health.', '5', '8', '["Gross margin declining quarter on quarter despite revenue growth", "Cost of serving enterprise customers significantly higher than SMB customers but pricing not adjusted", "Operational costs growing as a percentage of revenue rather than declining", "Founder reporting revenue growth positively but not monitoring gross margin trends", "Unit economics improving on acquisition but deteriorating on cost to serve"]', '6', 'Revenue Management at Scale', '["SAL-003", "OPS-004", "SCL-017"]', '2026-07-10 13:31:56.95582+00', '2026-08-03 03:26:49.954558+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('65', 'SCL-020', 'Sales Compensation Complexity', 'Scaling & Operational Maturity', 'external', 'As sales teams grow, founders have to design fair and effective commission structures. Get it wrong and either the company overpays for bad deals, or salespeople leave because they are underpaid for good performance.', '4', '7', '["Sales team gaming commission structure by closing deals that are bad for the business long-term", "Top sales performers leaving citing compensation as the primary reason", "Commission plan so complex that reps cannot calculate their own earnings", "Sales behaviour not aligned with business priorities because the incentives point the wrong way", "Significant commission disputes or errors in calculation each month"]', '6', 'Revenue Management at Scale', '["SCL-013", "TM-004", "OPS-004"]', '2026-07-10 13:31:56.95582+00', '2026-08-03 03:26:49.668108+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('66', 'SCL-021', 'Revenue Compliance and Reporting Complexity', 'Scaling & Operational Maturity', 'external', 'Larger contracts and multiple types of revenue mean new accounting and reporting requirements that early-stage founders rarely anticipate. Skipping this creates risk during due diligence or audits.', '4', '7', '["Revenue recognition approach has not been reviewed by an accountant as the business scales", "Deferred revenue not tracked properly for subscription or upfront-payment contracts", "Financial reports cannot distinguish between ARR, MRR, and one-time revenue correctly", "Audit or investor due diligence revealing revenue reporting errors", "Tax treatment of different revenue streams not clearly documented and reviewed"]', '6', 'Revenue Management at Scale', '["OPS-006", "OPS-004", "SCL-012"]', '2026-07-10 13:31:56.95582+00', '2026-08-03 03:26:50.001146+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('67', 'SCL-022', 'Customer Loss Costs More Than It Appears', 'Scaling & Operational Maturity', 'external', 'Once the business gets bigger, even a small increase in customers leaving has a big financial impact. Founders who were used to chasing new deals often do not build the systems needed to track and improve retention until the damage is already visible.', '6', '9', '["Churn rate not monitored at account or revenue level — only at user count level", "No early warning system for at-risk accounts — churn only discovered at renewal", "Customer success team reactive rather than proactive", "LTV declining year over year as average customer tenure shortens", "Net Revenue Retention below 100% making growth targets mathematically harder to hit"]', '6', 'Revenue Management at Scale', '["SAL-005", "SCL-015", "GTM-007"]', '2026-07-10 13:31:56.95582+00', '2026-08-03 03:26:49.71627+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('68', 'SCL-023', 'No Real Financial Planning System', 'Scaling & Operational Maturity', 'external', 'Many growing companies rely on spreadsheets long after they should have invested in proper financial planning. Without understanding key numbers, founders end up reacting to problems instead of seeing them coming.', '5', '8', '["Financial planning done in spreadsheets with no version control or scenario modelling", "No rolling 12-month financial forecast updated monthly", "Founder cannot quickly answer what happens to runway if revenue is missed by 20%", "Board receives financial updates that are backward-looking only — no forward projections", "Financial planning is seasonal or event-driven rather than a continuous management process"]', '6', 'Revenue Management at Scale', '["OPS-004", "OPS-005", "SCL-017"]', '2026-07-10 13:31:56.95582+00', '2026-08-03 03:26:50.051145+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('69', 'SCL-024', 'Leading Through Managers Instead of Directly', 'Scaling & Operational Maturity', 'external', 'Once the team grows, the founder has to hire managers and lead through them instead of working with everyone directly. This is a hard shift that founders often struggle with.', '5', '8', '["Founder bypassing managers and directing individual contributors directly", "Managers feeling undermined and disempowered by founder interference", "Inconsistent communication of company direction between founder and managers", "Founder spending time on operational details that managers should be handling", "Team receiving conflicting instructions from the founder and their direct manager"]', '5', 'People Management Complexity', '["SCL-011", "SCL-004", "TM-006"]', '2026-07-10 13:31:56.95582+00', '2026-08-03 03:26:50.097402+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('70', 'SCL-025', 'No Performance Management System', 'Scaling & Operational Maturity', 'external', 'In a small team, everyone just knew how they were doing. As the company grows, without a proper system for feedback and reviews, people do not know where they stand and top performers go unrecognised.', '5', '8', '["No regular performance review process — feedback only given informally or when there is a problem", "Top performers leaving because their contribution is not recognised or rewarded", "Underperformers staying because addressing performance feels uncomfortable", "Employees unclear about what doing well looks like in their role", "Compensation not connected to performance — everyone gets the same raise"]', '5', 'People Management Complexity', '["SCL-024", "TM-004", "SCL-027", "TM-030"]', '2026-07-10 13:31:56.95582+00', '2026-08-03 19:13:44.523023+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('71', 'SCL-026', 'No Succession Planning or Key Person Risk', 'Scaling & Operational Maturity', 'external', 'Founders rarely think about what happens if a key person leaves until it actually happens. Without a plan for who could step into important roles, losing one person can seriously disrupt the whole company.', '4', '7', '["No documented backup plan for any critical role including the founder", "Critical institutional knowledge held only by one or two people", "Key person departure would immediately create a crisis with no clear resolution path", "Investors or board have flagged key person dependency as a risk", "No development plan to grow internal candidates into senior roles"]', '5', 'People Management Complexity', '["SCL-003", "TM-005", "SCL-024"]', '2026-07-10 13:31:56.95582+00', '2026-08-03 03:26:50.150136+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('72', 'SCL-027', 'Compensation and Equity Complexity', 'Scaling & Operational Maturity', 'external', 'Early on, compensation is simple. As the team grows, founders have to figure out fair and competitive pay and equity for very different types of roles. Getting this wrong causes resentment and makes it hard to attract talent.', '4', '7', '["No compensation bands or benchmarking — salaries negotiated ad-hoc case by case", "Pay inequity discovered between people doing equivalent roles at different times of hiring", "Equity pool insufficient to offer meaningful grants to senior new hires", "Vesting schedules inconsistent across the team causing resentment", "Losing candidates to competitors who are offering more structured compensation packages"]', '5', 'People Management Complexity', '["TM-001", "TM-004", "SCL-025"]', '2026-07-10 13:31:56.95582+00', '2026-08-03 03:26:50.470677+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('73', 'SCL-028', 'Culture Failing to Scale Intentionally', 'Scaling & Operational Maturity', 'external', 'In a small team, culture is just how the founder behaves. At a larger size, culture has to be intentionally built through onboarding and rituals, or it fades and different departments start developing their own separate culture.', '5', '8', '["New hires reporting a culture very different from what was described during recruitment", "Different departments with noticeably different norms, communication styles, and values", "Core values documented somewhere but not reflected in day-to-day decisions or behaviour", "Founder surprised to hear how their own behaviour is described by team members", "Culture cited as a reason for departure by multiple exiting employees"]', '5', 'People Management Complexity', '["TM-006", "SCL-007", "SCL-029"]', '2026-07-10 13:31:56.95582+00', '2026-08-03 03:26:50.194867+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('74', 'SCL-029', 'Employee Disconnection and Morale Decline', 'Scaling & Operational Maturity', 'external', 'The closeness that kept a small team motivated does not scale automatically. As the company grows, people can start to feel unheard or overworked, and founders often miss the warning signs until good people start leaving.', '5', '8', '["Employee engagement scores declining quarter on quarter", "Increase in absenteeism, sick leave, or disengaged behaviour", "Good people leaving without a clear external reason — citing culture or leadership", "Team not speaking up in meetings where previously there was active debate", "Founder first learns about morale problems when a key person submits their resignation"]', '5', 'People Management Complexity', '["SCL-028", "TM-006", "SCL-025"]', '2026-07-10 13:31:56.95582+00', '2026-08-03 03:26:50.516305+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('75', 'SCL-030', 'Internal Politics and Competing Interests', 'Scaling & Operational Maturity', 'external', 'More people means more competing interests and opinions. Conflicts over credit, resources, or strategy that never used to exist start showing up, and without a clear way to resolve them, this quietly drains energy.', '5', '8', '["Teams competing for budget or headcount rather than collaborating", "Credit for successes being disputed between teams", "Informal alliances forming that influence decisions in ways not visible to leadership", "Meetings used to position rather than solve problems", "Key decisions being lobbied for informally rather than decided through clear process"]', '5', 'People Management Complexity', '["SCL-005", "TM-006", "SCL-009"]', '2026-07-10 13:31:56.95582+00', '2026-08-03 03:26:50.241004+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('76', 'SCL-031', 'New Managers Not Equipped to Lead', 'Scaling & Operational Maturity', 'external', 'Promoting someone into a leadership role does not automatically make them a good leader. Most growing companies do not invest in training their new managers, leaving skill gaps that hold the whole team back.', '5', '8', '["Newly promoted managers reverting to doing individual work instead of leading", "Team members under new managers performing worse than when managed by founder directly", "New managers avoiding difficult conversations — feedback and performance issues left unaddressed", "No manager training programme or coaching support provided after promotion", "High attrition within specific teams under new managers who were promoted without support"]', '5', 'People Management Complexity', '["SCL-024", "SCL-025", "TM-004"]', '2026-07-10 13:31:56.95582+00', '2026-08-03 03:26:47.248394+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('77', 'SCL-032', 'Role Ambiguity and Unclear Career Paths', 'Scaling & Operational Maturity', 'external', 'In a small team, roles are flexible and that is fine. At scale, without clearly defined roles and a path for growth, people get confused about what they are responsible for and talented people leave because they see no future.', '4', '7', '["Tasks falling through the cracks because ownership is unclear", "Talented people leaving citing lack of growth opportunities", "Team members spending significant time on work outside their defined role without direction", "No job descriptions updated as the company has grown", "Duplicate work happening because two people both thought they owned the same task"]', '5', 'People Management Complexity', '["SCL-009", "SCL-025", "SCL-031"]', '2026-07-10 13:31:56.95582+00', '2026-08-03 03:26:47.293958+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('78', 'SCL-033', 'No Organisational Health Monitoring', 'Scaling & Operational Maturity', 'external', 'Once the company is too big for the founder to sense problems just by walking around, there needs to be a deliberate way to check in on morale and culture. Without this, problems build quietly until they explode.', '4', '7', '["No employee engagement surveys, pulse checks, or structured feedback mechanisms", "Founder relies on informal conversations to assess morale rather than systematic data", "Culture or morale problems only discovered after they have already caused significant attrition", "No forum for employees to raise concerns anonymously", "Leadership team surprised by how employees actually feel about the company direction"]', '5', 'People Management Complexity', '["SCL-029", "SCL-028", "TM-006"]', '2026-07-10 13:31:56.95582+00', '2026-08-03 03:26:47.371566+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('79', 'SCL-034', 'Rapid Competitor Entry After Proof of Concept', 'Scaling & Operational Maturity', 'external', 'As soon as a startup proves its concept, competitors start copying it or undercutting on price. The early advantage of being first fades quickly, and founders need real strategies like branding or strong customer relationships to stay ahead.', '5', '8', '["Multiple direct competitors have entered the market since the company launched", "Larger incumbents launching similar features or products in response to startup traction", "Pricing pressure increasing as competitors undercut to gain share", "Win rates declining as prospects have more alternatives to evaluate", "No defensible moat beyond first-mover advantage which is already eroding"]', '6', 'Competitive and Market Maturity', '["SCL-035", "SCL-037", "GTM-004"]', '2026-07-10 13:31:56.95582+00', '2026-08-03 03:26:50.562182+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('80', 'SCL-035', 'Original Competitive Advantage Eroding', 'Scaling & Operational Maturity', 'external', 'What once felt like a unique solution can slowly become just another option in the market. Founders often struggle to shift from chasing short-term growth toward building something that genuinely protects their position long-term.', '5', '8', '["Differentiation claimed in sales conversations not meaningfully different from competitors", "Product features that were unique 12 months ago now standard across the category", "No new defensible competitive advantage built since initial traction", "Sales team losing deals to competitors who have closed the feature gap", "Founder unable to clearly articulate the moat that protects the business in 3 years"]', '6', 'Competitive and Market Maturity', '["SCL-034", "SCL-037", "PRD-005"]', '2026-07-10 13:31:56.95582+00', '2026-08-03 03:26:48.680509+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('81', 'SCL-036', 'Evolving Customer Expectations at Scale', 'Scaling & Operational Maturity', 'external', 'As a product becomes more mainstream, the type of customer buying it changes too — bigger, more demanding customers who expect more reliability, security, and support. Founders used to serving early enthusiastic users are often not ready for this shift.', '5', '8', '["Enterprise prospects requesting security certifications, SLAs, and compliance docs that do not exist", "New customer segments requiring features and support levels early customers never needed", "Customer success team stretched by enterprise customer demands beyond their capacity", "Deals lost due to lack of enterprise-grade reliability, uptime, or support", "Product roadmap driven by early adopter needs that no longer match the evolving customer base"]', '6', 'Competitive and Market Maturity', '["PRD-004", "SCL-034", "SCL-008"]', '2026-07-10 13:31:56.95582+00', '2026-08-03 03:26:51.366047+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('82', 'SCL-037', 'Market Commoditisation and Price Compression', 'Scaling & Operational Maturity', 'external', 'Once a solution clearly works, many competitors enter and the product starts to feel the same as everyone else. Founders can find themselves competing only on price, which slowly shrinks profit margins.', '6', '9', '["Average selling price declining quarter on quarter driven by competitive pressure", "Prospects treating the product as a commodity and negotiating only on price", "Gross margin declining as pricing drops to match competitors", "No premium positioning or brand advantage to justify higher pricing", "Product differentiation in sales conversations reduced to price and availability"]', '6', 'Competitive and Market Maturity', '["SCL-034", "SCL-035", "GTM-005"]', '2026-07-10 13:31:56.95582+00', '2026-08-03 03:26:51.312751+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('83', 'SCL-038', 'Innovation Pressure vs Execution Focus', 'Scaling & Operational Maturity', 'external', 'Once the initial idea works, there is pressure to keep evolving to stay ahead — but spreading into too many new areas too fast can dilute focus, while moving too slowly lets competitors catch up.', '5', '8', '["Multiple new product lines launched before existing products are fully optimised", "Core product quality stagnating while resources go to new feature development", "Team context-switching between too many initiatives reducing depth of execution", "Competitors improving on the founder core product while the team chases new markets", "Innovation initiatives not connected to a clear strategic rationale for the timing"]', '6', 'Competitive and Market Maturity', '["PRD-005", "SCL-035", "SCL-001"]', '2026-07-10 13:31:56.95582+00', '2026-08-03 03:26:48.777689+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('84', 'SCL-039', 'Platform or Ecosystem Dependency Risk', 'Scaling & Operational Maturity', 'external', 'Many businesses now depend on fitting into bigger ecosystems — app stores, marketplaces, cloud platforms. Founders who did not build these relationships early can find themselves outcompeted by businesses that did.', '5', '8', '["Business critically dependent on one platform for distribution with no alternative", "Platform policy change that would significantly disrupt the business model is possible", "Revenue heavily concentrated through one marketplace or app store", "Competitor gaining advantage through preferred platform partner status", "Building own ecosystem because preferred platform access was not secured early enough"]', '6', 'Competitive and Market Maturity', '["SCL-034", "SCL-041", "GTM-003"]', '2026-07-10 13:31:56.95582+00', '2026-08-03 03:26:50.288419+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('85', 'SCL-040', 'Customer Loyalty Declining in Mature Market', 'Scaling & Operational Maturity', 'external', 'As markets mature, customers have more choices and less patience. Founders need to shift from simply closing sales to actively managing relationships and building loyalty.', '5', '8', '["Average customer tenure shortening year on year", "Churn among long-standing customers increasing — not just new customers", "No formal customer success or relationship management programme", "Customers switching to competitors after small pricing or feature differences", "NPS declining despite the product not significantly changing"]', '6', 'Competitive and Market Maturity', '["SCL-022", "SAL-005", "SCL-037"]', '2026-07-10 13:31:56.95582+00', '2026-08-03 03:26:51.412981+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('86', 'SCL-041', 'Strategic Partnership Dependency and Governance', 'Scaling & Operational Maturity', 'external', 'Partnerships can speed up growth, but they also create dependency. If a key partner changes direction or strategy, the impact on revenue and plans can be severe.', '5', '8', '["Revenue significantly dependent on one or two channel or technology partners", "No formal partner agreement or SLA governing the partnership commitments", "Partner changing terms or priorities that materially impacts the business", "No alternative go-to-market if a key partner relationship ends", "Partner relationship managed informally with no regular governance structure"]', '6', 'Competitive and Market Maturity', '["SCL-039", "TM-005", "SCL-034"]', '2026-07-10 13:31:56.95582+00', '2026-08-03 03:26:50.334479+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('87', 'SCL-042', 'International Expansion Complexity', 'Scaling & Operational Maturity', 'external', 'Expanding into new countries means facing local competitors who understand that market better, along with new regulations and cultural differences. This stretches a founder focus and resources thin.', '5', '8', '["International markets consuming disproportionate management time relative to revenue generated", "Local compliance and regulatory requirements not fully understood before market entry", "Product not adapted for local market needs — assuming one-size-fits-all", "Core home market underperforming because leadership attention is split across geographies", "International team lacking the local expertise to compete effectively against local players"]', '6', 'Competitive and Market Maturity', '["SCL-034", "OPS-006", "SCL-001"]', '2026-07-10 13:31:56.95582+00', '2026-08-03 03:26:50.615663+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('88', 'SCL-043', 'Founder Struggling to Shift from Doing to Leading', 'Scaling & Operational Maturity', 'external', 'Founders who used to be deeply hands-on now need to think about the business as a whole rather than doing the detailed work themselves. This shift is emotionally hard and necessary for the company to grow.', '6', '9', '["Founder still doing technical, operational, or sales work that managers should own", "Team members not growing because the founder always steps in before they can figure it out", "Founder value-add concentrated in execution rather than strategy and leadership", "Business growing in revenue but not in organisational capability or independence", "Founder describing themselves primarily by what they build rather than what they lead"]', '6', 'Founder Role Evolution', '["SCL-011", "SCL-004", "OPS-002"]', '2026-07-10 13:31:56.95582+00', '2026-08-03 03:26:50.380424+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('89', 'SCL-044', 'Inability to Trust and Delegate to Team', 'Scaling & Operational Maturity', 'external', 'Stepping back from execution requires real trust in the team, which many founders struggle with. Holding onto everything actually slows the company down and can lead straight to burnout.', '6', '9', '["Founder redoing work completed by team members because it was not done their way", "Managers leaving because they are given responsibility without real authority", "Founder spending evenings and weekends checking on work that team members handled during the day", "Team has stopped showing initiative because they know the founder will take over anyway", "Founder acknowledges need to delegate but finds specific reasons not to for each task"]', '6', 'Founder Role Evolution', '["SCL-043", "SCL-011", "OPS-002"]', '2026-07-10 13:31:56.95582+00', '2026-08-03 03:26:50.663192+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('90', 'SCL-045', 'Managing Experienced Executives for the First Time', 'Scaling & Operational Maturity', 'external', 'At this stage, founders often work with experienced executives for the first time — a CFO, a VP of Sales — and have to learn how to manage people who may know more than them in certain areas.', '5', '8', '["Tension or conflict between the founder and newly hired senior executives", "Experienced hires leaving within 6-12 months citing lack of autonomy", "Founder undermining executive decisions in front of the broader team", "Senior executives not given enough context or involvement in strategy to be effective", "Founder reverting to doing the executive job rather than managing them"]', '6', 'Founder Role Evolution', '["SCL-024", "SCL-044", "TM-002"]', '2026-07-10 13:31:56.95582+00', '2026-08-03 03:26:50.708515+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('91', 'SCL-046', 'Dealing with a Formal Board for the First Time', 'Scaling & Operational Maturity', 'external', 'What used to be an informal company now often has a formal board with investors expecting structure — regular meetings, clear reporting. This is a big shift for founders both in terms of new processes and psychologically sharing control they used to hold alone.', '4', '7', '["Board meetings poorly prepared — no structured pack sent in advance", "Founder avoiding difficult conversations with the board about performance", "Board requests for information that the founder cannot provide because systems do not exist", "Investor concerns raised in board meetings that the founder was not aware of beforehand", "Founder describing board meetings as a source of stress rather than strategic support"]', '6', 'Founder Role Evolution', '["TM-005", "FND-004", "SCL-043"]', '2026-07-10 13:31:56.95582+00', '2026-08-03 03:26:48.726892+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('92', 'SCL-047', 'Investor Relations Becoming a Full-Time Job', 'Scaling & Operational Maturity', 'external', 'As funding rounds grow, so does the number of people the founder is accountable to. Managing investor expectations and updates becomes its own job.', '4', '7', '["Investors calling or emailing directly when they feel information is not flowing adequately", "No structured investor update cadence — updates sent ad-hoc or only when good news available", "Investor decisions being made based on incomplete or delayed information", "Founder spending significant time managing investor anxiety rather than building the business", "Different investors receiving different versions of the company performance story"]', '6', 'Founder Role Evolution', '["FND-004", "SCL-046", "TM-005"]', '2026-07-10 13:31:56.95582+00', '2026-08-03 03:26:48.916213+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('93', 'SCL-048', 'Balancing Operational Urgency with Long-Term Vision', 'Scaling & Operational Maturity', 'external', 'Founders constantly feel pulled between dealing with what is urgent right now and planning for where the business needs to be years from now. Get too caught up in daily fires and the business drifts without direction.', '5', '8', '["Founder calendar dominated by tactical problem-solving with no protected time for strategy", "Long-term planning sessions cancelled repeatedly to deal with operational issues", "Company strategy not documented or communicated beyond the founder", "Team operating without a clear sense of 12-month direction because founder has not articulated it", "Strategic initiatives started but abandoned halfway when operational demands overtake them"]', '6', 'Founder Role Evolution', '["SCL-043", "SCL-001", "OPS-005"]', '2026-07-10 13:31:56.95582+00', '2026-08-03 03:26:51.459048+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('94', 'SCL-049', 'Balancing Innovation with Operational Structure', 'Scaling & Operational Maturity', 'external', 'A growing company has to keep innovating like a startup while also running like a more structured business — and these two things can pull against each other.', '4', '7', '["Founder resisting process or documentation requests because they want to stay agile", "Quality and consistency problems cited by customers as the company scales", "Innovation happening but not being converted into reliable repeatable delivery", "Team frustrated by inconsistent standards — creative freedom without operational discipline", "New product capabilities launched without stable operational support behind them"]', '6', 'Founder Role Evolution', '["SCL-038", "OPS-001", "SCL-043"]', '2026-07-10 13:31:56.95582+00', '2026-08-03 03:26:51.503276+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('95', 'PSY-001', 'High Mental Health Burden and Psychological Distress', 'Founder Psychology', 'internal', '72% of founders report psychological symptoms significantly higher than the general population. Around 30% experience depression, 29% ADHD, and 49% have more than one mental health condition. This is not weakness — it is the reality of building under extreme uncertainty, financial pressure, and constant responsibility for others. Left unaddressed, this directly degrades the quality of decisions, leadership, and execution.', '7', '10', '["Founder reports persistent anxiety, low mood, or difficulty concentrating that has lasted more than two weeks", "Sleep disrupted consistently — either unable to sleep or sleeping far more than usual", "Physical symptoms appearing — headaches, chest tightness, exhaustion not resolved by rest", "Founder describes feeling disconnected from why they are building or what the point is", "Irritability or emotional outbursts that the founder recognises as out of character for them"]', '1', 'Mental Health', '["PSY-004", "PSY-007", "PSY-009"]', '2026-07-10 13:39:44.638144+00', '2026-08-03 03:26:48.823886+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('96', 'PSY-002', 'Identity Fusion with the Business', 'Founder Psychology', 'internal', 'Founders tie their identity so deeply to the startup that when the business struggles, they take it personally. Failures feel like personal failures, not business problems. This makes it very hard to pivot, accept criticism, or ask for help — because doing so feels like admitting they themselves are not good enough.', '6', '9', '["Founder uses I failed instead of the product failed when describing a business setback", "Critical feedback about the product is received as personal criticism and triggers defensiveness", "Unable to consider a pivot because it feels like admitting the original idea — and therefore themselves — was wrong", "Self-worth visibly tied to revenue numbers, investor opinion, or press coverage", "Founder describes their entire identity through the lens of the company — cannot speak about who they are outside of it"]', '1', 'Identity and Self-Worth', '["PSY-001", "PSY-005", "PSY-008"]', '2026-07-10 13:39:44.638144+00', '2026-08-03 03:26:51.548457+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('97', 'PSY-003', 'Stigma Around Seeking Mental Health Support', 'Founder Psychology', 'internal', 'About 25% of founders avoid seeking mental health help because they fear it will damage their reputation or make investors lose confidence. This silence makes things worse over time — unaddressed stress compounds into burnout, poor decisions, and leadership breakdown.', '5', '8', '["Founder explicitly says they cannot talk to anyone about how they are feeling because of how it would look", "Dismisses suggestions to speak to a therapist, coach, or peer group with I am fine or I do not have time", "Presents constant optimism and energy publicly while describing exhaustion and doubt privately", "Has not shared their real state with their co-founder, spouse, or any trusted person", "Equates asking for help with weakness or incompetence"]', '1', 'Mental Health', '["PSY-001", "PSY-004", "PSY-013"]', '2026-07-10 13:39:44.638144+00', '2026-08-03 03:26:48.869802+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('98', 'PSY-004', 'Chronic Anxiety and Pressure-Driven Behaviour Swings', 'Founder Psychology', 'internal', 'Under extreme stress, founders swing between bursts of high energy and complete paralysis. Over 86% of founders work more than 40 hours per week, and more than 50% report chronic anxiety. This inconsistency confuses their teams and affects the quality of every decision they make.', '6', '9', '["Team describes the founder mood as unpredictable — some days highly energised, other days withdrawn or irritable", "Founder makes rapid decisions under pressure and reverses them days later when calmer", "Unable to concentrate on strategic tasks because mind is constantly running worst-case scenarios", "Physical manifestation of anxiety — unable to sit still, racing thoughts, difficulty finishing sentences", "High-pressure moments trigger either frantic overwork or complete avoidance of work"]', '1', 'Emotional Regulation', '["PSY-001", "PSY-007", "PSY-010"]', '2026-07-10 13:39:44.638144+00', '2026-08-03 03:26:45.785257+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('99', 'PSY-005', 'Hero Syndrome — Refusing to Delegate or Share Load', 'Founder Psychology', 'internal', 'Many founders refuse to delegate because they believe no one else can do things as well as they can. This creates a bottleneck where the entire company depends on one person. Hero syndrome is not about ego — it is often rooted in fear of losing control or fear that vulnerability will be interpreted as weakness.', '6', '9', '["Founder is the only person doing work across sales, product, operations, and people simultaneously", "Tasks delegated are taken back within days because the founder could not resist improving or changing them", "Team has stopped offering to help because they know the founder will redo their work anyway", "Founder describes their team as not ready yet for real responsibility — but this has been true for months", "Working 70+ hours per week while team operates at far lower capacity"]', '1', 'Control and Delegation', '["PSY-006", "PSY-008", "PSY-007"]', '2026-07-10 13:39:44.638144+00', '2026-08-03 03:26:46.172373+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('100', 'PSY-006', 'No Deliberate Coping or Recovery Strategy', 'Founder Psychology', 'internal', 'High-performing founders build deliberate recovery habits — exercise, mindfulness, peer support groups, regular breaks. Founders without any coping strategy eventually crash — not because they are weak, but because they never designed sustainability into their operating rhythm.', '5', '8', '["Founder has no consistent physical exercise, sleep schedule, or deliberate break from work", "Recovery is accidental — founder rests only when forced to by illness or complete exhaustion", "No peer community, mentor, or trusted person the founder speaks with regularly about the real state of things", "Founder describes their work schedule as always on with no protected personal time", "Performance inconsistent — periods of high output followed by crashes that take days or weeks to recover from"]', '1', 'Resilience and Recovery', '["PSY-007", "PSY-004", "PSY-001"]', '2026-07-10 13:39:44.638144+00', '2026-08-03 03:26:45.833215+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('101', 'PSY-007', 'Founder Burnout', 'Founder Psychology', 'internal', 'Founders are twice as likely to suffer depression as non-founders. Burnout happens in stages — exhaustion first, then cynicism and detachment, then a complete sense of ineffectiveness. By the time most founders recognise they are burned out, they are already in the third stage.', '7', '10', '["Founder reports feeling exhausted regardless of how much sleep they get", "Tasks that used to feel exciting now feel meaningless or like a burden", "Making simple decisions now takes disproportionate effort", "Increasing cynicism about the product, the market, or the team that was not present before", "Founder has missed multiple commitments or deadlines in the last month without a clear external reason"]', '1', 'Burnout', '["PSY-001", "PSY-004", "PSY-006"]', '2026-07-10 13:39:44.638144+00', '2026-08-03 03:26:46.219226+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('102', 'PSY-008', 'Weak Delegation Ability', 'Founder Psychology', 'internal', 'Only 1 in 4 founders naturally know how to delegate. The remaining 75% either hold on to too much work themselves or hand things off poorly. Founders who delegate well grow their companies 112% faster. Perfectionism creates invisible bottlenecks.', '6', '9', '["Founder consistently doing work that should be done by someone they have hired", "When tasks are delegated, the output is redone or heavily edited before it is used", "Team members say they do not feel trusted to make decisions in their own domain", "Founder describes delegation as having failed — but the task was not clearly defined before being handed off", "Key decisions cannot be made when the founder is unavailable — even for a single day"]', '1', 'Leadership Behaviour', '["PSY-005", "PSY-009", "PSY-006"]', '2026-07-10 13:39:44.638144+00', '2026-08-03 03:26:45.884356+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('103', 'PSY-009', 'Perfectionism Creating Invisible Bottlenecks', 'Founder Psychology', 'internal', 'Many founders set impossibly high standards and then feel let down when their team does not meet them. Instead of coaching the team to improve, they take the work back. This creates a cycle where the team never grows and the founder never has enough time.', '5', '8', '["Founder spends significant time polishing work that has already been completed by a team member", "Products, emails, or proposals delayed because the founder needs to review and improve them first", "Team members say they never feel their work is good enough regardless of effort", "Founder cannot ship anything without personally reviewing every detail", "Launch timelines consistently extended because something could be better — even when good enough would suffice"]', '1', 'Leadership Behaviour', '["PSY-008", "PSY-005", "PSY-010"]', '2026-07-10 13:39:44.638144+00', '2026-08-03 03:26:46.264711+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('104', 'PSY-010', 'Founder Fallacy — Believing Only They Have the Vision', 'Founder Psychology', 'internal', 'A very common pattern is when founders believe that they are the only one who truly understands the product or the mission. This leads to micromanagement, which kills team initiative and makes the best employees leave.', '5', '8', '["Founder regularly corrects how team members explain the product or mission — even when the explanation was accurate", "Cannot let team members represent the company externally without being present", "Best performers leaving citing a feeling that they cannot contribute meaningfully", "Ideas from team members dismissed quickly without serious consideration", "Founder cannot articulate how they would transfer their vision to someone else if needed"]', '1', 'Leadership Behaviour', '["PSY-008", "PSY-005", "PSY-009"]', '2026-07-10 13:39:44.638144+00', '2026-08-03 03:26:45.931153+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('105', 'PSY-011', 'Poor Communication When Delegating', 'Founder Psychology', 'internal', 'Handing off a task without clearly explaining the goal, the boundaries, and the expected output almost always results in disappointment. Delegation is not just about giving work away — it is about transferring understanding.', '4', '7', '["Tasks handed off with no written brief — just a verbal description of what is needed", "Team member completes task differently from what the founder envisioned because the goal was not clearly defined", "Founder frustrated repeatedly by delegation outcomes but does not change how they hand off work", "No check-in cadence defined when tasks are delegated — founder either micromanages or completely disappears", "Team members afraid to ask clarifying questions because the founder seems impatient when asked"]', '1', 'Leadership Behaviour', '["PSY-008", "PSY-009", "PSY-010"]', '2026-07-10 13:39:44.638144+00', '2026-08-03 03:26:46.310263+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('106', 'PSY-012', 'Overconfidence and Underestimation of Risk', 'Founder Psychology', 'internal', 'Founders tend to overestimate their ability to predict outcomes and underestimate risks. This leads to bold bets without adequate planning, and resistance to warning signs. Overconfidence feels like conviction — which is why it is so hard to catch.', '6', '9', '["Revenue and growth forecasts consistently more optimistic than actual outcomes by more than 30%", "Risks raised by advisors or team members dismissed without serious consideration", "Major decisions made quickly without identifying what would have to be true for them to be wrong", "Founder describes challenges as smaller than they appear to outsiders looking at the same data", "Pattern of launching before key risks have been mitigated — then firefighting when those risks materialise"]', '1', 'Decision-Making and Cognitive Biases', '["PSY-013", "PSY-014", "PSY-015"]', '2026-07-10 13:39:44.638144+00', '2026-08-03 03:26:47.882675+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('107', 'PSY-013', 'Sunk Cost Trap — Refusing to Stop a Failing Path', 'Founder Psychology', 'internal', 'Many founders keep investing time and money into something that is clearly not working, simply because they have already invested so much. The rational decision — cut losses and redirect — is blocked by the emotional weight of what has already been spent.', '6', '9', '["Continuing to invest resources in a product, channel, or hire that has shown no results for months", "Justifying continued investment with we have come too far to stop now", "Advisors or co-founders recommending a change but founder unable to act on the advice", "Shutting down or pivoting feels like failure rather than strategic intelligence", "Founder knows internally that something is not working but cannot bring themselves to say it"]', '1', 'Decision-Making and Cognitive Biases', '["PSY-014", "PSY-012", "PSY-002"]', '2026-07-10 13:39:44.638144+00', '2026-08-03 03:26:45.981214+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('108', 'PSY-014', 'Confirmation Bias and Echo Chamber Thinking', 'Founder Psychology', 'internal', 'Founders naturally seek out information that confirms what they already believe. They dismiss data that contradicts their plan and surround themselves with people who agree with them. The people closest to the founder often stop giving honest feedback because they have learned it is not welcome.', '6', '9', '["Advisory board, team, and investors all agree with the founder in every meeting — no real challenge or dissent", "Negative customer feedback dismissed as outliers while positive feedback amplified", "Market data that contradicts the plan is explained away rather than seriously investigated", "Founder surrounds themselves with people who share the same background, worldview, and perspective", "Team members privately disagree with direction but do not raise it because past challenges were dismissed"]', '1', 'Decision-Making and Cognitive Biases', '["PSY-012", "PSY-013", "PSY-015"]', '2026-07-10 13:39:44.638144+00', '2026-08-03 03:26:46.368061+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('109', 'PSY-015', 'Loss Aversion Blocking Necessary Pivots', 'Founder Psychology', 'internal', 'The fear of losing what has already been built is often stronger than the desire to build something better. This keeps founders stuck in strategies that are not working because changing course feels like losing — even when staying the same is the bigger risk.', '6', '9', '["Aware that the current strategy is not working but cannot make the decision to change it", "Pivot considered and discussed multiple times but always deferred in favour of giving the current approach one more month", "Framing the decision as losing what we built rather than gaining a better path", "Founder can articulate what a pivot would require but finds reasons why now is not the right time", "Staying in a failing strategy because changing it would mean telling investors or team the original direction was wrong"]', '1', 'Decision-Making and Cognitive Biases', '["PSY-013", "PSY-014", "PSY-002"]', '2026-07-10 13:39:44.638144+00', '2026-08-03 03:26:46.032433+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('110', 'PSY-016', 'Decision Paralysis Under Pressure', 'Founder Psychology', 'internal', 'When stakes are high, many founders avoid making decisions altogether. They delay, ask for more data, or keep revisiting the same options. Decision paralysis is often mistaken for thoroughness — but it is a fear response masquerading as diligence.', '6', '9', '["Key decisions pending for weeks or months without resolution", "Founder keeps requesting more data before deciding — but the data that would make them certain does not exist", "Same decision revisited in multiple meetings without reaching a conclusion", "Team frustrated by inability to move forward because they are waiting on a founder decision", "Founder describes important choices as complicated when the core issue is discomfort with uncertainty"]', '1', 'Decision-Making and Cognitive Biases', '["PSY-012", "PSY-004", "PSY-015"]', '2026-07-10 13:39:44.638144+00', '2026-08-03 03:26:45.673775+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('111', 'PSY-017', 'No Structured Goal-Setting or Execution System', 'Founder Psychology', 'internal', 'Most founders set goals but never measure them. Having ambition is not the same as having a system. Many early-stage founders operate on instinct and energy rather than structured goals and review rhythms.', '5', '8', '["Founder cannot state their top 3 priorities for this week and why they are the priority", "Goals set at the start of a quarter but never reviewed or measured during the quarter", "Team working hard but not clearly aligned on what matters most right now", "Same problems discussed in every leadership meeting with no system for resolution and follow-through", "Progress measured by how busy people are rather than what outcomes were achieved"]', '1', 'Execution and Accountability', '["PSY-018", "PSY-019"]', '2026-07-10 13:39:44.638144+00', '2026-08-03 03:26:46.079757+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('112', 'PSY-018', 'Reactive Mode — Urgency Crowding Out Importance', 'Founder Psychology', 'internal', 'When founders respond to whatever feels most urgent in the moment rather than what is most important for the business, they create a culture of chaos. Everything feels urgent, nothing important gets done, and the team mirrors the founder reactive energy.', '5', '8', '["Founder calendar is driven entirely by what lands in their inbox rather than their own agenda", "Strategic initiatives started but consistently interrupted and never completed", "Most of the founder day spent on reactive tasks — responding to problems rather than creating forward momentum", "Team operates in a constant state of urgency because the founder treats everything as a fire", "No protected time for deep work, strategic thinking, or important but non-urgent priorities"]', '1', 'Execution and Accountability', '["PSY-017", "PSY-019", "PSY-004"]', '2026-07-10 13:39:44.638144+00', '2026-08-03 03:26:46.550429+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('113', 'PSY-019', 'No Accountability Culture in the Team', 'Founder Psychology', 'internal', 'Teams where people openly report missed targets, discuss failures, and hold each other to commitments grow faster than teams where difficult conversations are avoided. Founders who avoid accountability conversations create teams where nobody is ever really responsible for anything.', '5', '8', '["Missed commitments go unaddressed — no conversation happens and the same person misses again", "Team members do not know what each other commitments are — no shared visibility", "Performance problems known to everyone but not addressed because it feels uncomfortable", "Post-project reviews never happen — lessons from failures are never systematically captured", "Founder avoids confronting underperformance because they fear the conversation will damage the relationship"]', '1', 'Execution and Accountability', '["PSY-017", "PSY-018"]', '2026-07-10 13:39:44.638144+00', '2026-08-03 03:26:46.127068+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('114', 'PSY-020', 'Psychological Safety Absent from Team Culture', 'Founder Psychology', 'internal', 'Google Project Aristotle found that the number one factor separating high-performing teams from average ones was psychological safety: the feeling that team members can speak up, admit mistakes, and disagree without fear of punishment. When psychological safety is absent, problems hide until they become crises.', '6', '9', '["Team members never disagree with the founder in meetings — every idea gets immediate agreement", "Bad news arrives late — problems are only surfaced when they are already serious", "Team members ask what the founder thinks before sharing their own view", "Mistakes hidden or explained away rather than openly discussed and learned from", "High performers leaving and citing an inability to contribute their real thinking"]', '1', 'Organisational Behaviour and Team Dynamics', '["PSY-021", "PSY-019", "PSY-002"]', '2026-07-10 13:39:44.638144+00', '2026-08-03 03:26:46.596203+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('115', 'PSY-021', 'Founder Behaviour Setting a Toxic Team Culture', 'Founder Psychology', 'internal', 'Whatever the founder tolerates, ignores, or rewards becomes the culture — regardless of what is written on the company website. If the founder dismisses feedback, the team stops giving it. The founder is the single biggest cultural lever in any early-stage company.', '6', '9', '["Founder publicly dismisses or overrides team members contributions in group settings", "Founder visibly rewards people who agree with them and ignores or marginalises those who challenge", "Company values stated on website or in meetings but directly contradicted by founder daily behaviour", "Team has learned that honesty is risky — they tell the founder what they want to hear", "High attrition among strong performers who cite values mismatch as the reason for leaving"]', '1', 'Organisational Behaviour and Team Dynamics', '["PSY-020", "PSY-019", "PSY-002"]', '2026-07-10 13:39:44.638144+00', '2026-08-03 03:26:45.736274+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('116', 'PSY-022', 'Toxic Team Dynamics — Blame Culture and Political Behaviour', 'Founder Psychology', 'internal', 'Blame culture, fear of conflict, and political behaviour in teams are often invisible until they have already done serious damage. By the time it becomes visible, it has usually been building for months.', '6', '9', '["When something goes wrong, conversations focus on who is at fault rather than what went wrong in the system", "Team members protecting their own position rather than solving the problem together", "Conflicts between individuals or teams not addressed — founder avoids these conversations hoping they will resolve", "Projects failing for the same reasons repeatedly because the actual cause is never honestly discussed", "Information is shared selectively — team members withholding context from each other for political reasons"]', '1', 'Organisational Behaviour and Team Dynamics', '["PSY-020", "PSY-021", "PSY-019"]', '2026-07-10 13:39:44.638144+00', '2026-08-03 03:26:46.642257+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('117', 'PSY-023', 'Low Conscientiousness — Poor Follow-Through and Discipline', 'Founder Psychology', 'internal', 'Research consistently shows that successful entrepreneurs score significantly higher on conscientiousness — discipline, follow-through, and achievement orientation — than average managers. Founders who are high on vision but low on conscientiousness create companies that feel exciting but never gain real traction.', '6', '9', '["Many ideas started but few finished — a trail of incomplete initiatives", "Commitments made to team, investors, or customers consistently not followed through", "Brilliant in brainstorming and strategy sessions but misses on execution consistently", "Difficulty maintaining any system, process, or habit for more than a few weeks", "Team learns not to rely on the founder commitments because the track record of follow-through is poor"]', '1', 'High-Performance Founder Patterns', '["PSY-017", "PSY-018", "PSY-019"]', '2026-07-10 13:39:44.638144+00', '2026-08-03 03:26:46.830531+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('118', 'PSY-024', 'Low Openness — Resistance to New Information and Change', 'Founder Psychology', 'internal', 'High-performing founders are unusually comfortable with uncertainty and novelty. They welcome new information, change their minds when the evidence demands it, and treat pivots as intelligent responses rather than failures. Low openness manifests as rigidity.', '6', '9', '["Founder holds the same position in a conversation despite being presented with strong counter-evidence", "New market data or customer feedback that contradicts the current strategy is explained away quickly", "The founder view of the business has not meaningfully changed despite months of new evidence", "Discomfort or irritability when conversations challenge the original plan or thesis", "Team members have stopped bringing contradictory information because they know it will not be received"]', '1', 'High-Performance Founder Patterns', '["PSY-014", "PSY-013", "PSY-015"]', '2026-07-10 13:39:44.638144+00', '2026-08-03 03:26:46.686993+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('119', 'PSY-025', 'Lack of Grit — Dropping Out Before the Breakthrough', 'Founder Psychology', 'internal', 'Duckworth research on grit shows that sustained passion combined with consistent effort over time predicts success better than raw talent or intelligence. Founders who quit at the first or second serious obstacle do not give their idea enough runway to find what works.', '6', '9', '["Founder is considering shutting down at a stage where most successful companies also faced similar difficulties", "Motivation described as depleted — not temporarily tired but fundamentally disconnected from why they started", "Evidence of quitting when things got difficult in past ventures or commitments", "Conflating a bad month or a failed experiment with proof that the whole idea does not work", "Difficulty distinguishing between a setback that requires persistence and a fundamental problem that requires a pivot"]', '1', 'High-Performance Founder Patterns', '["PSY-007", "PSY-001", "PSY-006"]', '2026-07-10 13:39:44.638144+00', '2026-08-03 03:26:46.876725+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('120', 'PSY-026', 'Poor Emotional Self-Regulation Under Pressure', 'Founder Psychology', 'internal', 'The ability to stay calm under pressure, make clear decisions when things are uncertain, and project steadiness to the team is what makes a founder someone people want to follow. Founders who are emotionally reactive create anxious, uncertain teams.', '6', '9', '["Founder raises voice, uses sharp language, or shuts down conversations during high-pressure moments", "Team visibly adjusts their behaviour based on the founder mood on a given day", "Founder makes decisions in anger or panic that they later regret and reverse", "Key stakeholders — investors, customers, team — describe the founder as unpredictable under stress", "Emotional reactions in meetings consistently derail productive conversations"]', '1', 'Emotional Regulation', '["PSY-004", "PSY-020", "PSY-021"]', '2026-07-10 13:39:44.638144+00', '2026-08-03 03:26:46.737895+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('121', 'PSY-027', 'No Deliberate Daily Operating Habits', 'Founder Psychology', 'internal', 'High-performing founders do not rely on motivation — they rely on systems. Daily routines, regular reflection, consistent physical health habits, and structured learning time are what allow them to sustain high performance over long periods without burning out.', '4', '7', '["No consistent morning or evening routine — every day starts reactively from the phone", "Physical health deteriorating — irregular sleep, poor diet, no exercise — without a plan to address it", "No time blocked for deep work, reflection, or personal learning", "Founder relies on motivation and energy rather than structure — when motivation dips, productivity collapses", "No weekly reflection practice — same mistakes repeated because there is no deliberate review of what happened"]', '1', 'Resilience and Recovery', '["PSY-006", "PSY-007", "PSY-018"]', '2026-07-10 13:39:44.638144+00', '2026-08-03 03:26:47.928111+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('122', 'PSY-028', 'Imposter Syndrome', 'Founder Psychology', 'internal', 'Imposter syndrome is the persistent internal experience of believing that one is not as competent as others perceive them to be, and the fear of being found out as a fraud. In founders, this manifests as self-doubt that undermines decision-making, prevents asking for help, and creates constant anxiety.', '5', '8', '["Founder describes feeling like a fraud who will eventually be exposed despite external success", "Avoids situations that require them to claim expertise or authority because they feel unqualified", "Attributes successes to luck, timing, or other people rather than their own capability", "Difficulty accepting positive feedback or investor confidence at face value", "Holds back from conversations, pitches, or partnerships because they do not feel ready or qualified enough"]', '1', 'Identity and Self-Worth', '["PSY-002", "PSY-003", "PSY-012"]', '2026-07-10 13:39:44.638144+00', '2026-08-03 03:26:47.976373+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('123', 'PSY-029', 'Fear of Failure Blocking Action', 'Founder Psychology', 'internal', 'Fear of failure is one of the most pervasive psychological barriers in founders. It manifests not as a fear of trying — most founders try — but as a pattern of avoiding situations where failure is visible, delaying launches until conditions are perfect, and not making the bold moves the business actually requires.', '6', '9', '["Product launches, sales calls, and investor meetings consistently delayed because conditions are not right yet", "Founder avoids putting their idea in front of people who might give a negative verdict", "Major decisions deferred — framed as waiting for more information but actually avoiding the risk of being wrong", "Past failure used as a reason to be excessively cautious in situations that are actually lower risk", "Energy goes into preparation and planning rather than execution — staying busy while avoiding the actual moment of risk"]', '1', 'Identity and Self-Worth', '["PSY-002", "PSY-028", "PSY-016"]', '2026-07-10 13:39:44.638144+00', '2026-08-03 03:26:46.783407+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('124', 'PSY-030', 'Isolation and Lack of Founder Support Network', 'Founder Psychology', 'internal', 'Building a company is one of the loneliest experiences a person can have. Founders cannot share their real fears with their team, cannot be fully honest with investors, and often feel their personal relationships do not understand the reality of what they are going through. This isolation compounds every other psychological challenge.', '6', '9', '["Founder has no one they can speak to honestly about the real state of the business and how they are feeling", "Personal relationships strained because the founder cannot be present outside of work", "No peer founder community, coach, or mentor the founder speaks with regularly", "Founder makes all major decisions alone without a sounding board", "Describes the experience of building as fundamentally lonely — feeling that no one around them truly understands"]', '1', 'Mental Health', '["PSY-001", "PSY-003", "PSY-006"]', '2026-07-10 13:39:44.638144+00', '2026-08-03 03:26:46.920868+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('126', 'TCI-001', 'Customer Discovery Skipped or Superficial', 'Target Customer & ICP', 'external', 'The founder has not conducted real discovery conversations with potential customers, or has only spoken with friendly contacts who are inclined to be encouraging. Product and messaging decisions are being made without direct evidence of how the target customer actually thinks, speaks, or struggles.', '6', '9', '[]', '2', 'Discovery Practice', '["IVA-003", "TCI-011", "TCI-016"]', '2026-08-03 06:10:51.096205+00', '2026-09-13 06:26:33.588767+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('127', 'TCI-002', 'Persona Built on Assumption, Not Evidence', 'Target Customer & ICP', 'external', 'The founder has a written or mental customer persona, but it was constructed from imagination, a single conversation, or copied from a competitor, rather than built from a pattern across multiple real interviews. Decisions are being made against a fictional customer.', '5', '8', '[]', '2', 'Persona Accuracy', '["IVA-003", "TCI-011", "TCI-016"]', '2026-08-03 06:10:51.096205+00', '2026-09-13 06:26:33.588767+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('128', 'CMA-001', 'No Real Competitor Mapping Done', 'Competitive Awareness', 'external', 'The founder has not systematically identified who else is solving this problem, including indirect alternatives and the customer''s current workaround (often ''doing nothing'' or a manual process). Positioning and pricing decisions are being made blind to the actual competitive landscape.', '5', '8', '[]', '2', 'Landscape Awareness', '["CMA-015", "CMA-020", "CMA-025"]', '2026-08-03 06:10:51.096205+00', '2026-09-13 06:26:33.588767+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('129', 'CMA-002', 'Pricing Set Without Competitive Reference', 'Competitive Awareness', 'external', 'Price was chosen based on cost, gut feeling, or a round number, without checking what comparable alternatives charge or how the customer perceives value relative to those options. This creates a real risk of being dismissed as too expensive or undervalued as too cheap.', '4', '7', '[]', '2', 'Competitive Pricing', '["CMA-015", "CMA-020", "CMA-025"]', '2026-08-03 06:10:51.096205+00', '2026-09-13 06:26:33.588767+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('130', 'BMD-001', 'Unit Economics Never Calculated', 'Business Model Design', 'external', 'The founder does not know the cost to acquire a customer, the revenue or margin generated per customer over time, or whether each additional sale is profitable. Growth decisions are being made without knowing if the underlying economics actually work.', '6', '9', '[]', '3', 'Unit Economics', '["SAL-004", "BMD-016", "BMD-021", "BMD-026"]', '2026-08-03 06:22:33.145031+00', '2026-09-13 06:26:33.588767+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('131', 'BMD-002', 'No Framework Used to Compare Revenue Model Options', 'Business Model Design', 'external', 'A revenue model (subscription, one-time sale, commission, freemium, usage-based, etc.) was chosen without systematically weighing it against realistic alternatives for this specific business and customer base. The model may work by accident, or may be quietly working against the business.', '5', '8', '[]', '3', 'Revenue Model Selection', '["SAL-004", "BMD-016", "BMD-021", "BMD-026"]', '2026-08-03 06:22:33.145031+00', '2026-09-13 06:26:33.588767+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('132', 'BMD-016', 'Cost Structure Not Mapped to Revenue Model', 'Business Model Design', 'external', 'The founder can describe how money comes in, but has not mapped out the full cost structure (fixed costs, variable costs, one-time costs) against it to see whether the business model is actually sustainable at scale.', '5', '8', '[]', '3', 'Cost Structure', '["BMD-001", "BMD-002", "BMD-021", "BMD-026"]', '2026-08-03 06:44:11.534692+00', '2026-09-13 06:26:33.588767+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('133', 'CMA-015', 'No Response Plan for Competitor Moves', 'Competitive Awareness', 'external', 'The founder has thought about competitors in the abstract but has no actual plan for what to do if a competitor cuts price, copies a feature, or enters the same niche. Competitive moves would be reacted to in the moment rather than anticipated.', '4', '7', '[]', '2', 'Competitive Response', '["CMA-001", "CMA-002", "CMA-020", "CMA-025"]', '2026-08-03 06:44:11.534692+00', '2026-09-13 06:26:33.588767+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('134', 'GTM-028', 'No GTM Plan Built Before Launch', 'Go-To-Market', 'external', 'The founder is describing GTM activity that assumes a product is already live, but has not actually built a structured plan for launch itself — no defined sequence, no pre-built audience, no tested messaging. Launch is being treated as something that will happen rather than something being planned.', '6', '9', '[]', '2', 'Pre-Launch Planning', '["GTM-001", "GTM-003", "GTM-004"]', '2026-08-03 07:00:25.286197+00', '2026-08-03 07:01:59.889489+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('135', 'BMD-021', 'No Structured Business Model Framework Used', 'Business Model Design', 'external', 'The founder has pieced together fragments of a business model — maybe a price, maybe a rough sense of the customer — without ever laying out the full picture: value proposition, customer segments, channels, revenue streams, cost structure and key partners on one page. Decisions are being made about parts of the model without seeing how they connect.', '5', '8', '[]', '3', 'Model Design', '["BMD-001", "BMD-002", "BMD-016", "BMD-026"]', '2026-08-03 07:00:25.286197+00', '2026-09-13 06:26:33.588767+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('136', 'OPE-001', 'No Framework Used to Evaluate New Opportunities', 'Opportunity Evaluation', 'external', 'When new opportunities arise (a new market, a partnership, a pivot, a big customer request), the founder decides based on gut feeling or excitement in the moment, without a consistent way to weigh the opportunity against existing priorities, costs, and strategic fit.', '5', '8', '[]', '6', 'Evaluation Framework', '["OPE-002", "OPE-003", "OPE-016", "OPE-021"]', '2026-08-03 07:21:06.479942+00', '2026-09-13 06:26:33.588767+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('137', 'OPE-002', 'No Process for Saying No to Distracting Opportunities', 'Opportunity Evaluation', 'external', 'The founder struggles to decline opportunities that don''t fit, leading to a scattered focus across too many directions at once. Saying yes has become the default, and no clear process exists for declining gracefully and confidently.', '4', '7', '[]', '6', 'Prioritization Discipline', '["OPE-001", "OPE-003", "OPE-016", "OPE-021"]', '2026-08-03 07:21:06.479942+00', '2026-09-13 06:26:33.588767+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('138', 'OPE-003', 'No Method for Comparing Multiple Opportunities Against Each Other', 'Opportunity Evaluation', 'external', 'When several distinct opportunities exist at once (different markets, partnerships, or pivots), the founder has no side-by-side way to compare them — decisions are made sequentially and reactively as each one appears, rather than weighing them against each other.', '4', '7', '[]', '6', 'Comparative Decision-Making', '["OPE-001", "OPE-002", "OPE-016", "OPE-021"]', '2026-08-03 07:21:06.479942+00', '2026-09-13 06:26:33.588767+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('139', 'BPL-001', 'No Structured Planning Process for the Business', 'Business Planning', 'external', 'The founder operates reactively day-to-day, with no regular rhythm for stepping back to plan (weekly, quarterly, or annual). Decisions are made in the moment rather than against a plan that was deliberately set and is periodically revisited.', '5', '8', '[]', '6', 'Planning Cadence', '["BPL-002", "BPL-003", "BPL-016", "BPL-021"]', '2026-08-03 07:28:58.78377+00', '2026-09-13 06:26:33.588767+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('140', 'BPL-002', 'Goals Not Broken Down into Actionable Milestones', 'Business Planning', 'external', 'The founder has a sense of direction or a big goal, but it has never been broken into concrete, measurable, time-bound steps. It''s not clear what needs to happen this month, or this quarter, to actually move toward it.', '5', '8', '[]', '6', 'Goal Structuring', '["BPL-001", "BPL-003", "BPL-016", "BPL-021"]', '2026-08-03 07:28:58.78377+00', '2026-09-13 06:26:33.588767+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('141', 'BPL-003', 'No Contingency or Scenario Planning', 'Business Planning', 'external', 'The founder has one plan, built on a set of assumptions that have never been questioned. There''s no thinking about what would happen, or what the founder would do, if a key assumption turned out to be wrong.', '4', '7', '[]', '6', 'Scenario Planning', '["BPL-001", "BPL-002", "BPL-016", "BPL-021"]', '2026-08-03 07:28:58.78377+00', '2026-09-13 06:26:33.588767+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('142', 'RSK-001', 'No Systematic Way to Identify Business Risks', 'Risk Identification', 'external', 'The founder has never conducted a structured review of what could go wrong across the business — financial, legal, operational, market, or team risks. Whatever risks come to mind are ad hoc and incomplete, discovered only when something goes wrong.', '5', '8', '[]', '6', 'Risk Discovery', '["RSK-002", "RSK-003", "RSK-016", "RSK-021"]', '2026-08-03 08:08:28.209553+00', '2026-08-03 11:18:01.349889+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('143', 'RSK-002', 'Key Risks Known But Never Mitigated', 'Risk Identification', 'external', 'The founder can name real risks facing the business but has done nothing to actually reduce their likelihood or impact. Awareness exists without any corresponding action.', '5', '8', '[]', '6', 'Risk Mitigation', '["RSK-001", "RSK-003", "RSK-016", "RSK-021"]', '2026-08-03 08:08:28.209553+00', '2026-08-03 11:18:01.349889+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('144', 'RSK-003', 'Over-Reliance on a Single Point of Failure', 'Risk Identification', 'external', 'The business is dangerously dependent on one person, one customer, one supplier, or one channel — if that single thing disappeared, the business would be in serious trouble, and this concentration risk has never been explicitly addressed.', '6', '9', '[]', '6', 'Concentration Risk', '["RSK-001", "RSK-002", "TM-004", "RSK-016", "RSK-021"]', '2026-08-03 08:08:28.209553+00', '2026-08-03 11:18:01.349889+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('145', 'TCI-011', 'No Segmentation Beyond a Single Customer Type', 'Target Customer & ICP', 'external', 'The founder treats their entire customer base as one undifferentiated group, even though real usage patterns likely include distinct sub-segments with different needs, willingness to pay, or buying triggers. Product, messaging, and pricing decisions are made for a single ''average'' customer that may not represent anyone well.', '5', '8', '[]', '2', 'Customer Segmentation', '["TCI-001", "TCI-002", "IVA-003", "TCI-016"]', '2026-08-03 09:13:20.239155+00', '2026-09-13 06:26:33.588767+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('146', 'TCI-016', 'Customer Understanding Not Updated as Product Evolves', 'Target Customer & ICP', 'external', 'The founder''s mental model of their customer was built early on and has not been revisited even as the product, market, or customer base has changed significantly since. Decisions are being made based on an outdated picture of who''s actually buying and why.', '4', '7', '[]', '2', 'Customer Understanding Drift', '["TCI-001", "TCI-002", "IVA-003", "TCI-011"]', '2026-08-03 09:13:20.239155+00', '2026-09-13 06:26:33.588767+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('147', 'CMA-020', 'No Clear Differentiation from Competitors', 'Competitive Awareness', 'external', 'The founder struggles to articulate what genuinely sets the business apart from alternatives, beyond vague claims like ''better quality'' or ''better service.'' Without a specific, defensible point of difference, the business risks blending into the crowded set of options a customer is choosing from.', '5', '8', '[]', '2', 'Differentiation Clarity', '["CMA-001", "CMA-002", "CMA-015", "CMA-025"]', '2026-08-03 10:50:52.479496+00', '2026-09-13 06:26:33.588767+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('148', 'CMA-025', 'Competitor Strengths Never Studied for Learning', 'Competitive Awareness', 'external', 'The founder''s relationship with competitors is purely defensive or dismissive — competitors are seen as threats to react to or beat, never as a source of genuine learning about what''s working well for them that could inform this business.', '4', '7', '[]', '2', 'Competitive Learning', '["CMA-001", "CMA-002", "CMA-015", "CMA-020"]', '2026-08-03 10:50:52.479496+00', '2026-09-13 06:26:33.588767+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('149', 'OPE-016', 'No Post-Decision Review of Past Opportunity Choices', 'Opportunity Evaluation', 'external', 'After deciding to pursue or decline an opportunity, the founder never revisits that decision later to check whether it was actually the right call. Without this feedback loop, the same evaluation mistakes get repeated indefinitely.', '4', '7', '[]', '6', 'Decision Feedback Loop', '["OPE-001", "OPE-002", "OPE-003", "OPE-021"]', '2026-08-03 11:00:35.719899+00', '2026-09-13 06:26:33.588767+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('150', 'OPE-021', 'Opportunities Evaluated Without Input From Those They Affect', 'Opportunity Evaluation', 'external', 'When deciding whether to pursue a new opportunity, the founder doesn''t consult the team members or stakeholders who would actually be affected by or responsible for executing on it. Decisions are made in isolation, then handed down.', '4', '7', '[]', '6', 'Collaborative Evaluation', '["OPE-001", "OPE-002", "OPE-003", "OPE-016"]', '2026-08-03 11:00:35.719899+00', '2026-09-13 06:26:33.588767+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('151', 'BPL-016', 'Planning Done Alone, Never Shared or Communicated', 'Business Planning', 'external', 'Even where the founder does some planning, it stays private — in their head or a personal document — and is never communicated to the team or stakeholders who need to align their work to it. The plan exists, but nobody else can see or act on it.', '4', '7', '[]', '6', 'Plan Communication', '["BPL-001", "BPL-002", "BPL-003", "BPL-021"]', '2026-08-03 11:12:25.114879+00', '2026-09-13 06:26:33.588767+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('152', 'BPL-021', 'No Resource Planning Behind the Goals', 'Business Planning', 'external', 'The founder sets goals and plans without checking whether there''s actually enough time, money, or people available to execute them. Plans look good on paper but are disconnected from real capacity, setting the business up to fall short.', '5', '8', '[]', '6', 'Resource Planning', '["BPL-001", "BPL-002", "BPL-003", "BPL-016"]', '2026-08-03 11:12:25.114879+00', '2026-09-13 06:26:33.588767+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('153', 'RSK-016', 'No Legal or Compliance Risk Review Ever Done', 'Risk Identification', 'external', 'The founder has never had contracts, regulatory obligations, licensing requirements, or intellectual property protection reviewed by someone with the expertise to spot risk. Legal and compliance exposure is invisible until it becomes an actual problem.', '5', '8', '[]', '6', 'Legal & Compliance Risk', '["RSK-001", "RSK-002", "RSK-003", "RSK-021"]', '2026-08-03 11:16:55.832948+00', '2026-08-03 11:18:51.363716+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('154', 'RSK-021', 'Risk Ownership Unclear — Nobody Specifically Responsible', 'Risk Identification', 'external', 'Even where risks have been identified, no single person is clearly responsible for monitoring or managing any given risk. Risks exist as vague shared awareness rather than assigned ownership, so nothing actually gets tracked or acted on consistently.', '4', '7', '[]', '6', 'Risk Ownership', '["RSK-001", "RSK-002", "RSK-003", "RSK-016"]', '2026-08-03 11:16:55.832948+00', '2026-08-03 11:18:51.42826+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('155', 'BMD-026', 'Business Model Assumptions Never Tested Against Real Customer Behavior', 'Business Model Design', 'external', 'The business model relies on assumptions about how customers will actually behave — how often they''ll buy, how long they''ll stay, whether they''ll refer others — but these assumptions were guessed at the start and have never been checked against real, observed customer behavior.', '5', '8', '[]', '3', 'Model Validation', '["BMD-001", "BMD-002", "BMD-016", "BMD-021"]', '2026-08-03 11:28:31.885901+00', '2026-09-13 06:26:33.588767+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('156', 'SLX-001', 'No Structured Lead Qualification Process', 'Sales Execution', 'external', 'The founder pursues most or all leads that come in without a consistent way to assess fit, spending time and energy on prospects who are unlikely to buy while better-fit prospects may get less attention than they deserve.', '5', '8', '[]', '3', 'Lead Qualification', '["SAL-001", "SAL-002", "SLX-006", "SLX-011", "SLX-016", "SLX-021", "SLX-026", "SLX-036", "SLX-041", "SLX-046", "SLX-051", "SLX-116", "SLX-121", "SLX-126", "SLX-131", "SLX-136", "SLX-141", "SLX-146", "SLX-156", "SLX-161", "SLX-166", "SLX-171"]', '2026-08-03 12:57:05.377706+00', '2026-08-04 13:38:10.692434+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('157', 'SLX-006', 'No System for Writing Effective Outreach', 'Sales Execution', 'external', 'The founder sends outreach messages (cold emails, DMs, calls) without any structured approach to writing them — no testing, no personalization framework, no learning from what works. Each message is written from scratch with no accumulated practice.', '5', '8', '[]', '3', 'Outreach Messaging', '["SLX-001", "SAL-001", "SLX-011", "SLX-016", "SLX-056", "SLX-061", "SLX-066", "SLX-071"]', '2026-08-03 13:25:37.778334+00', '2026-08-04 06:15:54.012155+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('158', 'SLX-011', 'No Structured Process for Preparing Proposals', 'Sales Execution', 'external', 'Proposals or quotes sent to prospects are created from scratch each time, without a consistent structure, template, or process for tailoring them to what actually matters to that specific buyer. This slows down the sales process and risks looking unpolished or inconsistent.', '5', '8', '[]', '3', 'Proposal Preparation', '["SLX-001", "SLX-006", "SAL-002", "SLX-016", "SLX-021", "SLX-076", "SLX-081", "SLX-086", "SLX-091", "SLX-116"]', '2026-08-03 13:29:52.594926+00', '2026-08-04 12:58:55.022735+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('159', 'SLX-016', 'No Structured Follow-Up Cadence Across the Sales Process', 'Sales Execution', 'external', 'Following up with prospects happens inconsistently and depends entirely on the founder remembering, rather than a defined cadence. Prospects fall through the cracks, follow-ups repeat the same message with no new value, and there is no clear stopping point for chasing an unresponsive lead.', '5', '8', '[]', '3', 'Follow-Up Discipline', '["SLX-001", "SLX-006", "SLX-011", "SLX-096", "SLX-101", "SLX-106", "SLX-111", "SLX-126"]', '2026-08-03 15:49:54.760373+00', '2026-08-04 13:06:35.057727+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('160', 'SLX-021', 'No Structured Process for Analyzing Lost Deals', 'Sales Execution', 'external', 'When a deal is lost, the founder moves on without any systematic review of why it was lost — no post-mortem, no categorization of reasons, no pattern-spotting across multiple losses. Each loss is treated as an isolated event rather than a source of learning.', '5', '8', '[]', '3', 'Lost Deal Analysis', '["SLX-001", "SLX-011", "SAL-002", "SLX-026", "SLX-031", "SLX-116", "SLX-121", "SLX-126", "SLX-131", "SLX-136", "SLX-141"]', '2026-08-03 15:55:11.101955+00', '2026-08-04 13:17:59.433098+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('161', 'SLX-026', 'No Systematic Approach to Improving Conversion Rate', 'Sales Execution', 'external', 'The founder may know a rough conversion rate but has no structured way to actually improve it — no breakdown of where prospects drop off in the funnel, no testing of what changes actually help, and no benchmark for what a good rate even looks like for this type of business.', '5', '8', '[]', '3', 'Conversion Optimization', '["SLX-001", "SLX-021", "SAL-001", "SLX-111", "SLX-116", "SLX-121", "SLX-136", "SLX-141", "SLX-146", "SLX-151", "SLX-156"]', '2026-08-03 16:03:46.431425+00', '2026-08-04 13:28:35.234541+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('162', 'SLX-031', 'No Ongoing Customer or Account Management Process', 'Sales Execution', 'external', 'Once a customer signs, there is no ongoing process for managing that relationship — no regular check-ins, no clear owner, no way to spot a customer who is struggling or at risk before they churn. Customers are managed reactively, only when they reach out.', '5', '8', '[]', '3', 'Customer Relationship Management', '["SLX-021", "SAL-005", "SLX-116", "SLX-121", "SLX-156", "SLX-161", "SLX-166", "SLX-171"]', '2026-08-03 17:26:29.206673+00', '2026-08-04 13:38:10.692434+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('163', 'MEX-001', 'No Consistent Content Planning or Calendar', 'Marketing Execution', 'external', 'Marketing content (posts, articles, videos) gets created reactively whenever the founder has time or an idea, with no calendar, no planned cadence, and no consistent presence. Content output is sporadic rather than a sustained, planned practice.', '5', '8', '[]', '2', 'Content Planning', '["GTM-004", "MEX-006", "MEX-011", "MEX-016", "MEX-021", "MEX-026", "MEX-031", "MEX-036", "MEX-041", "MEX-046"]', '2026-08-03 17:39:44.245983+00', '2026-08-04 14:53:30.360035+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('164', 'MEX-006', 'No Reusable System for Generating Marketing Content', 'Marketing Execution', 'external', 'Each piece of marketing content is created entirely from scratch with no reusable process, templates, or system for turning ideas into finished content efficiently. Content creation is slow, inconsistent in quality, and heavily bottlenecked on the founder''s personal time and inspiration.', '5', '8', '[]', '2', 'Content Creation', '["MEX-001", "GTM-004", "MEX-011", "MEX-016", "MEX-021", "MEX-026", "MEX-031", "MEX-041", "MEX-046", "MEX-051", "MEX-056", "MEX-061", "MEX-066"]', '2026-08-03 17:44:25.158282+00', '2026-08-04 15:10:42.101432+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('165', 'MEX-011', 'No Structured Process for Planning Marketing Campaigns', 'Marketing Execution', 'external', 'Campaigns get launched based on a rough idea rather than a structured plan — no defined goal, target audience, budget, timeline, or channel selection thought through beforehand. Planning is minimal or skipped entirely before execution begins.', '5', '8', '[]', '2', 'Campaign Planning', '["MEX-001", "MEX-006", "MEX-016", "MEX-021", "MEX-041", "MEX-061", "MEX-066", "MEX-071", "MEX-076", "MEX-081", "MEX-086"]', '2026-08-03 17:48:28.525675+00', '2026-08-04 15:34:03.919872+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('166', 'MEX-016', 'No Structured Post-Campaign Analysis Process', 'Marketing Execution', 'external', 'After a campaign ends, there is no systematic review of what actually happened — no comparison against the original goal, no breakdown of what worked versus what did not, and no documented learnings carried into the next campaign. Each campaign is analyzed superficially, if at all, before moving to the next one.', '5', '8', '[]', '2', 'Campaign Analysis', '["MEX-001", "MEX-006", "MEX-011", "MEX-021", "MEX-026", "MEX-061", "MEX-081", "MEX-086", "MEX-091", "MEX-096", "MEX-101"]', '2026-08-03 17:52:54.683941+00', '2026-08-04 15:48:19.071459+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('167', 'FIN-001', 'No Ongoing Cash Flow Monitoring Process', 'Financial Management', 'external', 'The founder does not track cash flow on any regular basis — money in and out is only noticed reactively when the bank balance gets uncomfortably low, rather than monitored proactively through a forecast or dashboard.', '5', '8', '[]', '3', 'Cash Flow Monitoring', '["OPS-004", "SCL-018", "FIN-006", "FIN-011", "FIN-016", "FIN-021", "FIN-031", "FIN-036", "FIN-041", "FIN-046", "FIN-051", "FIN-056", "FIN-071", "FIN-076", "FIN-091", "FIN-096", "FIN-111", "FIN-116", "FIN-131"]', '2026-08-03 18:25:56.092966+00', '2026-08-05 07:01:28.129733+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('168', 'FIN-006', 'No Ongoing Runway Forecasting Discipline', 'Financial Management', 'external', 'The founder only calculates runway reactively, usually during a fundraise or financial crisis, rather than tracking it as an ongoing discipline. Burn rate and months of runway remaining are not monitored regularly enough to catch a worsening trajectory early.', '5', '8', '[]', '3', 'Runway Forecasting', '["FND-001", "FND-007", "FIN-001", "FIN-011", "FIN-016", "FIN-031", "FIN-036", "FIN-051", "FIN-056", "FIN-061", "FIN-066"]', '2026-08-03 18:31:52.604241+00', '2026-08-05 05:00:37.190655+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('169', 'FIN-011', 'Founder Cannot Read or Interpret Their Own P&L', 'Financial Management', 'external', 'The founder cannot confidently read or interpret their own profit and loss statement — line items, margins, and what is actually driving profitability or loss remain unclear, even though the statement itself may exist. Financial decisions get made on gut feel rather than by actually understanding the P&L.', '5', '8', '[]', '3', 'P&L Literacy', '["OPS-004", "FIN-001", "FIN-006", "FIN-016", "FIN-026", "FIN-031", "FIN-071", "FIN-076", "FIN-081", "FIN-086", "FIN-091", "FIN-131", "FIN-136"]', '2026-08-03 18:36:52.333762+00', '2026-08-05 07:07:05.371482+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('170', 'FIN-016', 'No Structured Process for Building a Budget', 'Financial Management', 'external', 'The founder does not have a real process for building a budget — spending decisions get made ad hoc, without a plan that ties expected revenue to planned costs across departments or categories. Whatever budget exists, if any, was not built from a clear method and is not used to guide actual spending decisions.', '5', '8', '[]', '3', 'Budget Building', '["SCL-017", "FIN-001", "FIN-006", "FIN-011", "FIN-021", "FIN-071", "FIN-091", "FIN-096", "FIN-101", "FIN-106", "FIN-111"]', '2026-08-03 18:41:21.113759+00', '2026-08-05 05:40:30.730005+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('171', 'FIN-021', 'No Regular Process for Reviewing Business Expenses', 'Financial Management', 'external', 'The founder does not regularly review what the business is actually spending money on — recurring subscriptions, vendor costs, and discretionary spend accumulate without anyone checking whether they are still needed or providing value. Spending drifts upward unnoticed.', '4', '7', '[]', '3', 'Expense Review', '["FIN-001", "FIN-016", "FIN-026", "FIN-111", "FIN-116", "FIN-121", "FIN-126"]', '2026-08-03 18:50:42.165232+00', '2026-08-05 06:57:47.241353+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('173', 'FIN-026', 'No Regular Financial Reporting Practice', 'Financial Management', 'external', 'The founder does not have a regular practice of producing and reviewing financial reports — statements get generated occasionally or only when required externally (taxes, a lender, an investor), rather than as an ongoing habit that informs real decisions.', '4', '7', '[]', '3', 'Financial Reporting', '["SCL-012", "OPS-004", "FIN-011", "FIN-021", "FIN-131", "FIN-136", "FIN-141", "FIN-146", "FIN-151"]', '2026-08-03 18:58:48.994773+00', '2026-08-05 07:25:56.529222+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('174', 'TM-025', 'No Onboarding Plan for a Founder''s First Hires', 'Team & Leadership', 'external', 'When making an early hire (the founder''s first employee or first few), there is no structured onboarding plan — no clear first-week structure, no documented expectations, and no deliberate process for helping a first hire ramp up. What onboarding exists, if any, is informal and improvised, unlike the more developed onboarding practices typically built for later-stage teams.', '5', '8', '[]', '5', 'Early-Stage Onboarding', '["TM-004", "SCL-007", "TM-030", "TM-035", "TM-041", "TM-046", "TM-051", "TM-056", "TM-061"]', '2026-08-03 19:02:38.221255+00', '2026-08-06 04:20:00.533585+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('175', 'TM-030', 'No Way to Track Performance for a Founder''s First Few Hires', 'Team & Leadership', 'external', 'With only a handful of employees, the founder has no simple way to track how each person is actually performing — no clear expectations to measure against, no regular check-in on progress, and no early signal when someone is struggling. What exists for larger teams (formal performance systems) does not apply yet, but nothing has replaced it for a small team.', '5', '8', '[]', '5', 'Early-Stage Performance Tracking', '["SCL-025", "TM-025", "TM-035", "TM-041", "TM-056", "TM-061", "TM-066", "TM-071", "TM-076"]', '2026-08-03 19:12:36.599961+00', '2026-08-06 04:37:02.675593+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('176', 'OPS-021', 'No Practice of Creating or Maintaining SOPs', 'Operations & Systems', 'external', 'Even where the founder knows a process should be documented, there is no actual practice of writing, maintaining, or using SOPs (standard operating procedures) — knowledge stays in the founder''s head or gets repeated verbally each time rather than written down once and reused.', '5', '8', '[]', '4', 'SOP Creation', '["OPS-001", "OPS-026", "OPS-031", "OPS-036", "OPS-041", "OPS-046"]', '2026-08-03 19:15:48.507644+00', '2026-08-06 04:57:19.190858+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('177', 'OPS-026', 'No Company Policies or Employment Documentation', 'Operations & Systems', 'external', 'The business has no written company policies or employee documentation — no employee handbook, no documented expectations around conduct, leave, or basic workplace rules, and no employment contracts beyond perhaps a verbal agreement. As the team grows, this creates ambiguity and risk.', '5', '8', '[]', '4', 'Company Policies', '["OPS-002", "OPS-021", "TM-004", "OPS-031", "OPS-051", "OPS-056", "OPS-061", "OPS-066"]', '2026-08-03 19:18:42.362916+00', '2026-08-06 05:16:44.841254+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('178', 'SLX-036', 'No Lead Scoring System to Prioritize Multiple Leads', 'Sales Execution', 'external', 'When multiple leads come in around the same time, there is no scoring or ranking system to decide which to prioritize first — leads get worked in whatever order they arrived or whichever feels most urgent in the moment, rather than by actual likelihood to close.', '5', '8', '[]', '3', 'Lead Prioritization', '["SLX-001", "SLX-041", "SLX-046", "SLX-051"]', '2026-08-04 05:13:40.66966+00', '2026-08-04 05:37:34.288223+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('179', 'SLX-041', 'No Process for Nurturing Leads That Aren''t Ready Yet', 'Sales Execution', 'external', 'Some leads are a genuine fit but simply aren''t ready to buy yet — wrong timing, not urgent, need to check back later. There is no process for nurturing these leads over time; they either get treated the same as ready-to-buy leads or get dropped entirely and forgotten.', '4', '7', '[]', '3', 'Lead Nurturing', '["SLX-001", "SLX-036", "SLX-046", "SLX-051"]', '2026-08-04 05:23:59.778038+00', '2026-08-04 05:37:34.288223+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('180', 'SLX-046', 'No Structured Qualifying Conversation Framework', 'Sales Execution', 'external', 'Even when the founder knows roughly what to look for in a lead, there is no structured way to actually run the qualifying conversation itself — no consistent set of questions to ask in what order, no way to read buying signals in real time, and the conversation often turns into a pitch rather than genuine discovery.', '5', '8', '[]', '3', 'Qualifying Conversation Skill', '["SLX-001", "SLX-036", "SLX-041", "SLX-051"]', '2026-08-04 05:30:44.209254+00', '2026-08-04 05:37:34.288223+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('181', 'SLX-051', 'Qualification Criteria Never Validated Against Actual Customer Success', 'Sales Execution', 'external', 'Even where some qualification criteria exist, they were set based on assumption rather than checked against which past leads actually converted and became successful, satisfied customers. The criteria may be filtering for the wrong signals entirely.', '4', '7', '[]', '3', 'Criteria Validation', '["SLX-001", "SLX-036", "SLX-041", "SLX-046", "IVA-003"]', '2026-08-04 05:36:35.149768+00', '2026-08-04 05:38:24.516116+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('182', 'SLX-056', 'No Research Process to Personalize Outreach Before Sending', 'Sales Execution', 'external', 'Before reaching out to a prospect, there is no process for actually researching who they are, what they care about, or what is relevant to them specifically — messages get sent based on generic assumptions about the target audience rather than anything learned about the individual prospect.', '4', '7', '[]', '3', 'Pre-Outreach Research', '["SLX-006", "SLX-061", "SLX-066", "SLX-071"]', '2026-08-04 05:43:30.235764+00', '2026-08-04 06:15:54.012155+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('183', 'SLX-061', 'No Strategic Channel Selection for Initial Outreach', 'Sales Execution', 'external', 'The founder defaults to one channel for all initial outreach (usually email) without considering which channel the specific prospect is actually most likely to respond to, or without ever testing whether a different channel would perform better for reaching this audience.', '4', '7', '[]', '3', 'Channel Strategy', '["SLX-006", "SLX-056", "SLX-066", "SLX-071"]', '2026-08-04 05:52:28.409644+00', '2026-08-04 06:15:54.012155+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('184', 'SLX-066', 'No Compelling Opening Line or Hook to Earn Attention', 'Sales Execution', 'external', 'The opening line or subject line of outreach messages fails to earn attention — it is generic, self-focused, or unremarkable, so prospects do not feel compelled to keep reading even when the rest of the message might be relevant.', '4', '7', '[]', '3', 'Opening Line Craft', '["SLX-006", "SLX-056", "SLX-061", "SLX-071"]', '2026-08-04 06:01:22.726607+00', '2026-08-04 06:15:54.012155+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('185', 'SLX-071', 'No Clear Call-to-Action in Outreach Messages', 'Sales Execution', 'external', 'Outreach messages often end without a clear, specific ask — the prospect is not told exactly what to do next, or the ask is too big (e.g. ''let''s hop on a 30-minute call'') for someone who barely knows the founder yet, leading to messages that get read but not acted on.', '4', '7', '[]', '3', 'Call-to-Action Design', '["SLX-006", "SLX-056", "SLX-061", "SLX-066"]', '2026-08-04 06:04:40.420417+00', '2026-08-04 06:16:40.27821+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('186', 'SLX-076', 'No Structured Process for Handling Objections Within a Proposal', 'Sales Execution', 'external', 'Proposals present the offer without anticipating or addressing the objections a prospect is likely to have — concerns about price, risk, timing, or how this compares to alternatives are left for the prospect to raise, or not raise and just walk away, rather than being proactively addressed within the proposal itself.', '5', '8', '[]', '3', 'Objection Handling in Proposals', '["SLX-011", "SLX-081", "SLX-086", "SLX-091"]', '2026-08-04 06:18:40.853344+00', '2026-08-04 06:52:05.423433+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('187', 'SLX-081', 'No Pre-Proposal Confirmation of Scope, Budget, or Decision Process', 'Sales Execution', 'external', 'The proposal is written and sent without confirming key assumptions (scope, budget range, timeline, decision process) with the prospect beforehand — it is a one-way document created in isolation rather than something shaped by a conversation, increasing the risk it misses what the prospect actually needs.', '5', '8', '[]', '3', 'Pre-Proposal Alignment', '["SLX-011", "SLX-076", "SLX-086", "SLX-091"]', '2026-08-04 06:31:23.264344+00', '2026-08-04 06:52:05.423433+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('188', 'SLX-086', 'No Structured Process for Presenting or Walking Through the Proposal', 'Sales Execution', 'external', 'The proposal is simply sent (emailed, shared as a link) without any process for walking the prospect through it live — no presentation, no opportunity to answer questions in real time, leaving the prospect to interpret the document entirely on their own.', '4', '7', '[]', '3', 'Proposal Presentation', '["SLX-011", "SLX-076", "SLX-081", "SLX-091"]', '2026-08-04 06:35:12.0275+00', '2026-08-04 06:52:05.423433+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('189', 'SLX-091', 'No Sense of Urgency or Decision Deadline Built Into Proposals', 'Sales Execution', 'external', 'Proposals are sent with no expiration date, no time-limited incentive, and no clear reason for the prospect to decide by any particular point — leaving deals to drift indefinitely without any natural pressure to move forward.', '4', '7', '[]', '3', 'Proposal Urgency Design', '["SLX-011", "SLX-076", "SLX-081", "SLX-086"]', '2026-08-04 06:51:07.712873+00', '2026-08-04 06:52:56.184321+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('190', 'SLX-096', 'No Differentiation in Follow-Up Approach Based on Why the Prospect Went Quiet', 'Sales Execution', 'external', 'When a prospect goes quiet, the founder assumes the same reason every time (usually ''not interested'') and follows up the same way regardless of what might actually be going on — busy, forgot, lost the message, or genuinely reconsidering — rather than adapting the follow-up approach based on the likely real reason.', '4', '7', '[]', '3', 'Silence Diagnosis', '["SLX-016", "SLX-101", "SLX-106", "SLX-111"]', '2026-08-04 06:55:06.051863+00', '2026-08-04 10:34:01.564678+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('191', 'SLX-101', 'No Escalation or Change in Approach When Standard Follow-Up Isn''t Working', 'Sales Execution', 'external', 'When the standard follow-up sequence does not get a response after several attempts, there is no escalation or change in approach — the founder either keeps repeating the same type of touch or simply gives up, rather than trying something meaningfully different to break through.', '4', '7', '[]', '3', 'Follow-Up Escalation', '["SLX-016", "SLX-096", "SLX-106", "SLX-111"]', '2026-08-04 06:59:58.808279+00', '2026-08-04 10:34:01.564678+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('192', 'SLX-106', 'No System for Tracking Follow-Up History Per Prospect', 'Sales Execution', 'external', 'There is no record of the follow-up history for each prospect — how many touches have happened, when, and what was said — so follow-ups risk repeating the same message, contradicting an earlier one, or losing track of where things actually stand with each person.', '4', '7', '[]', '3', 'Follow-Up History Tracking', '["SLX-016", "SLX-096", "SLX-101", "SLX-111"]', '2026-08-04 10:29:13.748817+00', '2026-08-04 10:34:01.564678+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('193', 'SLX-111', 'No Measurement of Follow-Up Effectiveness Over Time', 'Sales Execution', 'external', 'There is no measurement of which follow-up cadences, timings, or approaches actually lead to responses or conversions — follow-up practices stay static because there is no data showing what is working and what isn''t, so the same possibly ineffective approach continues indefinitely.', '4', '7', '[]', '3', 'Follow-Up Performance Measurement', '["SLX-016", "SLX-096", "SLX-101", "SLX-106", "SLX-026"]', '2026-08-04 10:32:59.867866+00', '2026-08-04 12:54:28.507032+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('194', 'SLX-116', 'Loss Analysis Insights Never Translate Into Changes', 'Sales Execution', 'external', 'Even when lost deals are reviewed and reasons identified, the findings stay isolated — no one is responsible for acting on them, they are not discussed with the team, and pricing, pitch, positioning, or targeting never actually change as a result. The business keeps losing deals to the same reason because the loop between insight and action is broken.', '5', '8', '[]', '3', 'Lost Deal Analysis', '["SLX-021", "SLX-001", "SLX-011", "SLX-026", "SLX-031", "SLX-121", "SLX-126", "SLX-131", "SLX-136"]', '2026-08-04 12:56:56.842951+00', '2026-08-04 13:14:56.694422+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('195', 'SLX-121', 'No Comparison Between Lost and Won Deals to Find What Actually Differs', 'Sales Execution', 'external', 'Loss analysis happens in isolation — only lost deals get scrutinized, while won deals are barely reviewed once closed. Without comparing similar deals that went opposite ways, the founder never verifies what actually separates a win from a loss, so beliefs about "why we win" and "why we lose" stay untested assumptions rather than confirmed patterns.', '5', '8', '[]', '3', 'Lost Deal Analysis', '["SLX-021", "SLX-116", "SLX-001", "SLX-026", "SLX-031", "SLX-126", "SLX-131"]', '2026-08-04 13:01:21.362385+00', '2026-08-04 13:09:41.901371+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('196', 'SLX-126', 'No Process for Identifying Which Lost Deals Could Be Revisited Later', 'Sales Execution', 'external', '"Lost" is treated as a single permanent status, with no distinction between a prospect who said no forever and one who said "not now" because of timing, budget cycles, or a decision-maker change. Without a re-engagement process, genuinely revivable prospects get filed away with the truly dead ones and disappear from the pipeline for good — even though many would convert if approached again at the right moment.', '5', '8', '[]', '3', 'Lost Deal Analysis', '["SLX-021", "SLX-116", "SLX-121", "SLX-001", "SLX-016", "SLX-131"]', '2026-08-04 13:05:41.962605+00', '2026-08-04 13:09:41.901371+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('197', 'SLX-131', 'No Competitive Intelligence Gathered From Lost Deals', 'Sales Execution', 'external', 'When a deal is lost to a competitor, there is no record of which competitor won, what they offered, or why they were chosen instead. Sales conversations do not probe for this information, findings are not aggregated across deals, and positioning or pricing never gets updated based on real competitive losses — so the founder is left guessing about the competitive landscape instead of learning from direct evidence.', '5', '8', '[]', '3', 'Lost Deal Analysis', '["SLX-021", "SLX-116", "SLX-121", "SLX-126", "SLX-001"]', '2026-08-04 13:08:52.185395+00', '2026-08-04 13:10:30.163481+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('198', 'SLX-136', 'No Visibility Into Which Lead Sources Convert Best', 'Sales Execution', 'external', 'Conversion rate, if tracked at all, is measured in aggregate and never broken down by where each lead actually came from — referral, cold outreach, inbound, events, paid ads. Without this breakdown, time, effort, and budget keep getting spread evenly or by gut feel across channels, even though some sources are likely converting dramatically better than others, and underperforming sources never get cut because nobody can prove they underperform.', '5', '8', '[]', '3', 'Conversion Rate Optimization', '["SLX-026", "SLX-001", "SLX-021", "SLX-116", "SLX-141", "SLX-146", "SLX-151"]', '2026-08-04 13:14:05.058574+00', '2026-08-04 13:25:15.785019+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('199', 'SLX-141', 'No Tracking of How Sales Cycle Length Affects Conversion', 'Sales Execution', 'external', 'Deals are tracked as won or lost, but how long each one took to close — or how long it dragged before dying — is never measured. Without this, stalled deals do not get flagged for intervention, the average sales cycle can quietly creep up over time unnoticed, and there is no evidence for whether a faster or slower process actually correlates with winning.', '5', '8', '[]', '3', 'Conversion Rate Optimization', '["SLX-026", "SLX-136", "SLX-001", "SLX-021", "SLX-146", "SLX-151"]', '2026-08-04 13:17:07.531321+00', '2026-08-04 13:25:15.785019+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('200', 'SLX-146', 'No Segmentation of Conversion Rate by Deal Size or Prospect Type', 'Sales Execution', 'external', 'Conversion rate, if tracked at all, is calculated as one blended average across every prospect, regardless of deal size, industry, or how closely they match the ideal customer profile. Without this segmentation, a strong-converting segment can be masked by a weak one in the average, and there is no way to tell where sales effort would actually produce the best return.', '5', '8', '[]', '3', 'Conversion Rate Optimization', '["SLX-026", "SLX-136", "SLX-141", "SLX-001", "SLX-151"]', '2026-08-04 13:20:33.543435+00', '2026-08-04 13:25:15.785019+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('201', 'SLX-151', 'No Tracking of Conversion Rate by Pricing or Packaging Offered', 'Sales Execution', 'external', 'When different prices, discounts, or package tiers are offered to different prospects, nobody tracks whether specific pricing or packaging structures convert better than others. Pricing decisions stay arbitrary or based on gut feel rather than evidence of what actually closes deals, and discounting patterns — who gets one, how much, whether it even helps — go completely unexamined.', '5', '8', '[]', '3', 'Conversion Rate Optimization', '["SLX-026", "SLX-136", "SLX-141", "SLX-146"]', '2026-08-04 13:24:27.5806+00', '2026-08-04 13:25:51.233532+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('202', 'SLX-156', 'No Process for Expanding Revenue From Existing Customers', 'Sales Execution', 'external', 'Customer management is treated purely as relationship maintenance and churn prevention — check-ins happen, but nobody systematically looks at what else an existing customer might need or want to buy. Expansion opportunities go unnoticed or unacted-on, no upsell or cross-sell offer is ever formally prepared or pitched, and revenue per customer stays flat after the first sale even when there is clear room to grow it.', '5', '8', '[]', '3', 'Customer & Account Management', '["SLX-031", "SLX-026", "SLX-001", "SLX-161", "SLX-166", "SLX-171"]', '2026-08-04 13:27:39.446923+00', '2026-08-04 13:38:10.692434+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('203', 'SLX-161', 'No Structured Process for Handling Customer Complaints or Issues', 'Sales Execution', 'external', 'When a customer raises a problem or complaint, there is no consistent process for logging it, tracking it to resolution, or learning from it. Issues get handled reactively and inconsistently depending on who happens to be available, resolution time is never measured, and recurring complaints never get identified or fixed at the root because nothing is tracked in one place.', '5', '8', '[]', '3', 'Customer & Account Management', '["SLX-031", "SLX-156", "SLX-001", "SLX-166", "SLX-171"]', '2026-08-04 13:31:33.451388+00', '2026-08-04 13:38:10.692434+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('204', 'SLX-166', 'No Process for Turning Satisfied Customers Into Referrals or Testimonials', 'Sales Execution', 'external', 'Customers who are clearly happy — renewing, referring casually, praising the product unprompted — are never systematically asked for a referral, review, or testimonial. Positive experiences stay locked with that one customer instead of being converted into new business or social proof, because there is no moment built into the relationship where this ask happens, and no easy process ready for when a customer says yes.', '5', '8', '[]', '3', 'Customer & Account Management', '["SLX-031", "SLX-156", "SLX-161", "SLX-001", "SLX-171"]', '2026-08-04 13:34:23.796048+00', '2026-08-04 13:38:10.692434+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('205', 'SLX-171', 'No Proactive Process for Managing Contract or Subscription Renewals', 'Sales Execution', 'external', 'Renewal or contract end dates are not tracked in one place, so renewals get handled reactively — sometimes only noticed when a customer already cancels or a payment fails. There is no advance outreach before a renewal comes due, no process for identifying at-risk renewals ahead of time, no measured renewal rate, and terms are never revisited at the renewal point.', '5', '8', '[]', '3', 'Customer & Account Management', '["SLX-031", "SLX-156", "SLX-161", "SLX-166", "SLX-001"]', '2026-08-04 13:37:18.754516+00', '2026-08-04 13:38:55.248994+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('206', 'MEX-021', 'No Connection Between the Content Calendar and Business or Marketing Goals', 'Marketing Execution', 'external', 'Even where a content calendar exists, it runs independently of what the business is actually trying to achieve — a launch, a promotion, a seasonal moment, a specific campaign. Content topics get filled in on a mechanical schedule rather than mapped to business priorities, the calendar is never revisited when priorities shift, and no extra content push happens around the moments that would benefit from one.', '5', '8', '[]', '2', 'Content Planning', '["MEX-001", "MEX-006", "MEX-011", "MEX-016", "MEX-026", "MEX-031", "MEX-036"]', '2026-08-04 13:57:50.448187+00', '2026-08-04 14:08:59.819878+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('207', 'MEX-026', 'No Platform-Specific Planning in the Content Calendar', 'Marketing Execution', 'external', 'The same piece of content, or the same planning approach, gets applied uniformly across every platform, without considering that each channel has a different audience, format expectation, and best practice. The calendar does not differentiate what should run where or adapt content to fit each platform, so content underperforms almost everywhere because it is optimized for none of them.', '5', '8', '[]', '2', 'Content Planning', '["MEX-001", "MEX-021", "MEX-006", "MEX-016", "MEX-031", "MEX-036"]', '2026-08-04 14:00:53.980808+00', '2026-08-04 14:08:59.819878+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('208', 'MEX-031', 'No Advance Planning Horizon — Content Decided Day-Of Rather Than Weeks Ahead', 'Marketing Execution', 'external', 'Even where some planning exists, content topics and posts are typically decided the same day or the day before they go out, rather than weeks in advance. This leaves no buffer for quality, no ability to batch-produce content efficiently, no room to plan around opportunities that require lead time, and the planning horizon shrinks even further whenever the founder gets busy.', '5', '8', '[]', '2', 'Content Planning', '["MEX-001", "MEX-021", "MEX-026", "MEX-006", "MEX-036"]', '2026-08-04 14:03:50.813674+00', '2026-08-04 14:08:59.819878+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('209', 'MEX-036', 'No Use of Seasonal or Industry Calendar Moments in Content Planning', 'Marketing Execution', 'external', 'Relevant holidays, awareness days, industry events, and seasonal moments that the target audience already cares about are not tracked or planned for, so content misses easy opportunities to be timely and relevant. Content stays generic year-round instead of tapping into moments the audience is already paying attention to, and seasonal opportunities are often only noticed after they have already passed.', '5', '8', '[]', '2', 'Content Planning', '["MEX-001", "MEX-021", "MEX-026", "MEX-031"]', '2026-08-04 14:08:10.04203+00', '2026-08-04 14:09:36.898616+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('210', 'MEX-041', 'No Use of Real Customer Questions or Conversations as Content Source Material', 'Marketing Execution', 'external', 'Real questions, objections, and pain points that come up in sales calls, support conversations, and customer interactions are never captured or turned into content. Instead of drawing on what customers are actually asking and struggling with, content topics get guessed from scratch each time, missing an abundant and highly relevant source of material that would resonate because it directly answers real questions.', '5', '8', '[]', '2', 'Content Creation', '["MEX-006", "MEX-001", "MEX-011", "MEX-046", "MEX-051", "MEX-056"]', '2026-08-04 14:11:19.245362+00', '2026-08-04 15:03:52.108694+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('211', 'MEX-046', 'No Defined Brand Voice or Style Guide for Content Creation', 'Marketing Execution', 'external', 'Content gets created without any documented voice, tone, or style standard to guide it, so pieces come out inconsistent — formal in one post, casual in the next, no unifying personality. Without a defined voice, content does not build a recognizable brand identity over time, tone shifts unintentionally, and if more than one person creates content, pieces sound noticeably different from each other.', '5', '8', '[]', '2', 'Content Creation', '["MEX-006", "MEX-041", "MEX-001", "MEX-051", "MEX-056"]', '2026-08-04 14:52:30.024786+00', '2026-08-04 15:03:52.108694+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('212', 'MEX-051', 'No Visual or Media Asset System to Support Content Creation', 'Marketing Execution', 'external', 'Every piece of content that needs an image, graphic, or video requires starting from scratch, because there is no library of reusable visual templates, past assets, or compiled brand elements (logo, colors, fonts) readily available. This slows down content creation, leads to inconsistent visual presentation, and often becomes the actual bottleneck even when the message or copy itself is ready to go.', '5', '8', '[]', '2', 'Content Creation', '["MEX-006", "MEX-041", "MEX-046", "MEX-056"]', '2026-08-04 14:55:40.674669+00', '2026-08-04 15:03:52.108694+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('213', 'MEX-056', 'No Editing or Quality Review Step Before Content Gets Published', 'Marketing Execution', 'external', 'Content goes straight from creation to publishing with no review step in between — no check for typos, unclear phrasing, broken links, factual accuracy, or overall polish. Errors and rough drafts go out under the brand''s name because there is no habit of pausing to review before hitting publish, and time pressure makes it easy to skip even when review would normally happen.', '5', '8', '[]', '2', 'Content Creation', '["MEX-006", "MEX-041", "MEX-046", "MEX-051"]', '2026-08-04 14:58:45.023391+00', '2026-08-04 15:04:32.426629+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('214', 'MEX-061', 'No Dedicated Landing Page or Conversion Path Planned for the Campaign', 'Marketing Execution', 'external', 'Campaign traffic gets sent to a generic homepage or contact page instead of a page built specifically for the campaign''s message and offer. Without a matching landing experience, the momentum built by the ad or promotion is lost the moment someone clicks through — the message does not match, there is no clear next step, and there is no way to measure how well the actual conversion path performs.', '5', '8', '[]', '2', 'Campaign Planning', '["MEX-011", "MEX-006", "MEX-016", "MEX-066", "MEX-071", "MEX-076", "MEX-081"]', '2026-08-04 15:06:31.86817+00', '2026-08-04 15:26:09.807243+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('215', 'MEX-066', 'No Coordination With Sales or Fulfillment Before a Campaign Launches', 'Marketing Execution', 'external', 'Campaigns get launched without briefing the people responsible for following up on leads or fulfilling any resulting demand. Sales does not know the campaign''s messaging, offer, or expected volume, so leads generated by the campaign get delayed, mishandled, or met with inconsistent follow-up — turning marketing spend into wasted opportunity, with no feedback loop back to marketing about how those leads actually performed.', '5', '8', '[]', '2', 'Campaign Planning', '["MEX-011", "MEX-061", "MEX-006", "MEX-071", "MEX-076"]', '2026-08-04 15:09:46.928588+00', '2026-08-04 15:22:47.852806+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('216', 'MEX-071', 'No Small-Scale Test Before Committing Full Campaign Budget', 'Marketing Execution', 'external', 'Campaigns launch with the full budget and audience commitment from day one, without first testing the message, audience, or channel on a small scale to see what actually works. Without this validation step, an unproven approach can burn through the entire budget before anyone learns whether it was the right one, and different messages or creatives never get compared before the business commits fully to one.', '5', '8', '[]', '2', 'Campaign Planning', '["MEX-011", "MEX-061", "MEX-066", "MEX-076"]', '2026-08-04 15:18:45.479942+00', '2026-08-04 15:22:47.852806+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('217', 'MEX-076', 'No Check of Competitive or Market Timing Before Launching a Campaign', 'Marketing Execution', 'external', 'Campaigns launch without checking what else is happening in the market at that moment — a competitor might be running something similar, the audience''s attention might be elsewhere, or broader industry timing could work against the campaign''s chances. Timing gets decided by internal readiness alone, without regard to external conditions, so campaigns sometimes compete against noise or launch into foreseeably unfavorable circumstances.', '5', '8', '[]', '2', 'Campaign Planning', '["MEX-011", "MEX-061", "MEX-066", "MEX-071"]', '2026-08-04 15:21:51.582995+00', '2026-08-04 15:23:28.909589+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('218', 'MEX-081', 'No Calculation of Campaign ROI or Cost-Efficiency', 'Marketing Execution', 'external', 'Even when a campaign''s basic metrics — clicks, leads, engagement — are tracked, nobody calculates what it actually cost to generate each result or whether the campaign was profitable relative to spend. Without this math, campaigns can look successful on the surface while actually losing money, and there is no way to compare campaigns against each other by true cost-efficiency.', '5', '8', '[]', '2', 'Campaign Analysis', '["MEX-016", "MEX-011", "MEX-061", "MEX-086", "MEX-091", "MEX-096", "MEX-101"]', '2026-08-04 15:25:14.458692+00', '2026-08-04 15:48:19.071459+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('219', 'MEX-086', 'No Channel-Level Attribution Within a Multi-Channel Campaign', 'Marketing Execution', 'external', 'When a campaign runs across multiple channels at once, results get reported as one blended number, with no way to tell which specific channel actually drove the leads or sales. Without channel-level attribution, budget keeps getting split the same way across channels regardless of which one is actually working, and underperforming channels never get identified or cut.', '5', '8', '[]', '2', 'Campaign Analysis', '["MEX-016", "MEX-081", "MEX-011", "MEX-091", "MEX-096", "MEX-101"]', '2026-08-04 15:33:05.741915+00', '2026-08-04 15:48:19.071459+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('220', 'MEX-091', 'No Audience Segment-Level Analysis of Campaign Performance', 'Marketing Execution', 'external', 'Campaign results get reported as one number across the whole audience, without breaking down performance by segment — age, industry, company size, geography, or other meaningful splits. Without this breakdown, a campaign that actually performed great with one segment and poorly with another looks like an average, mediocre result, and there is no way to learn which audience segment to focus on next time.', '5', '8', '[]', '2', 'Campaign Analysis', '["MEX-016", "MEX-081", "MEX-086", "MEX-096", "MEX-101"]', '2026-08-04 15:36:33.621438+00', '2026-08-04 15:48:19.071459+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('221', 'MEX-096', 'No Post-Campaign Analysis of Which Specific Message or Creative Resonated', 'Marketing Execution', 'external', 'When a campaign runs with multiple messages, headlines, or creative variations, nobody looks back afterward to see which one actually performed best. Without this analysis, every campaign risks repeating a message or creative approach that quietly underperformed, and there is no growing understanding of what actually resonates with the audience.', '5', '8', '[]', '2', 'Campaign Analysis', '["MEX-016", "MEX-081", "MEX-086", "MEX-091", "MEX-101"]', '2026-08-04 15:44:19.906782+00', '2026-08-04 15:48:19.071459+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('222', 'MEX-101', 'No Sharing of Campaign Results or Learnings With the Team', 'Marketing Execution', 'external', 'Even when a campaign gets analyzed, the results and learnings stay with whoever did the analysis and never reach the rest of the team — sales, other marketers, or the founder''s future self planning the next campaign. Without a habit of sharing, insights that could inform pricing, messaging, or targeting decisions elsewhere in the business never make it there, and the same lessons have to be relearned campaign after campaign.', '5', '8', '[]', '2', 'Campaign Analysis', '["MEX-016", "MEX-081", "MEX-086", "MEX-091", "MEX-096"]', '2026-08-04 15:47:27.620436+00', '2026-08-04 15:48:59.657356+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('223', 'FIN-031', 'No Tracking of Overdue Customer Payments', 'Financial Management', 'external', 'Money owed by customers who haven''t paid on time is not tracked anywhere systematic, so overdue invoices go unnoticed and uncollected. Cash that should already be in the bank stays stuck with customers, invisible to cash flow monitoring, and nobody follows up on late payments until the shortfall is already being felt.', '5', '8', '[]', '3', 'Cash Flow Monitoring', '["FIN-001", "FIN-006", "FIN-011", "FIN-036", "FIN-041", "FIN-046"]', '2026-08-04 15:51:17.048182+00', '2026-08-04 16:29:08.220011+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('224', 'FIN-036', 'No Tracking of What the Business Owes Others', 'Financial Management', 'external', 'Bills, vendor invoices, subscriptions, and other obligations the business owes are not tracked in one place, so the founder does not have a clear picture of what is coming due and when. Without this visibility, payments get made reactively when a vendor follows up or a service gets cut off, rather than proactively planned around cash flow.', '5', '8', '[]', '3', 'Cash Flow Monitoring', '["FIN-001", "FIN-031", "FIN-006", "FIN-041", "FIN-046"]', '2026-08-04 16:10:25.95686+00', '2026-08-04 16:29:08.220011+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('225', 'FIN-041', 'No Short-Term Cash Position Forecast Combining Known Receivables and Payables', 'Financial Management', 'external', 'Even where receivables and payables are tracked separately, they are never combined into a single short-term projection of what the actual cash position will look like in the coming weeks. Without this near-term forecast, the founder cannot see a cash crunch coming in time to act on it, and decisions get made based on today''s bank balance rather than where cash is realistically headed. Distinct from long-horizon runway/burn-rate planning — this is about the next few weeks of operational cash movement.', '5', '8', '[]', '3', 'Cash Flow Monitoring', '["FIN-001", "FIN-031", "FIN-036", "FIN-046"]', '2026-08-04 16:16:52.255393+00', '2026-08-04 16:29:08.220011+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('226', 'FIN-046', 'No Defined Action Plan for When Cash Gets Tight', 'Financial Management', 'external', 'Even where cash flow is monitored, there is no predetermined plan for what to actually do when the cash position gets tight — no ranked list of costs to cut, no threshold that triggers a decision, no plan for accessing additional cash if needed. When cash actually does get tight, decisions get made reactively and under stress, exactly when clear thinking is hardest.', '5', '8', '[]', '3', 'Cash Flow Monitoring', '["FIN-001", "FIN-031", "FIN-036", "FIN-041", "FIN-051"]', '2026-08-04 16:28:09.784616+00', '2026-08-04 16:32:58.686245+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('227', 'FIN-051', 'No Sharing of Runway Status With Co-Founders or Key Team Members', 'Financial Management', 'external', 'The runway number, even when calculated, stays known only to the founder — co-founders, key team members, or decision-makers do not know where things stand. Without shared visibility, hiring, spending, and other decisions get made across the team without anyone else understanding the real financial constraint they are operating under, and spending patterns continue unaware that runway is shrinking.', '5', '8', '[]', '3', 'Runway Forecasting', '["FIN-006", "FIN-001", "FIN-046", "FIN-056", "FIN-061", "FIN-066"]', '2026-08-04 16:31:58.567462+00', '2026-08-05 05:00:37.190655+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('228', 'FIN-056', 'No Connection Between Runway and When to Start Fundraising', 'Financial Management', 'external', 'Even when runway is known, there is no plan connecting that number to when a fundraising process should actually begin. Raising money takes months, but without working backward from runway, founders often start too late — either scrambling under pressure with a shrinking runway or missing the window to raise from a position of strength.', '5', '8', '[]', '3', 'Runway Forecasting', '["FIN-006", "FIN-051", "FIN-001", "FIN-061", "FIN-066"]', '2026-08-04 16:35:28.068073+00', '2026-08-05 05:00:37.190655+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('229', 'FIN-061', 'No Use of Runway Impact in Hiring or Major Spending Decisions', 'Financial Management', 'external', 'Big decisions — hiring a new person, signing a new tool contract, committing to a large purchase — get made without checking what they do to runway. Runway might be tracked in isolation, but it is not actually consulted as part of the decision process for new spending, so commitments pile up without anyone connecting them to how much runway they consume until the effect shows up later.', '5', '8', '[]', '3', 'Runway Forecasting', '["FIN-006", "FIN-051", "FIN-056", "FIN-066"]', '2026-08-05 04:54:37.852891+00', '2026-08-05 05:00:37.190655+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('230', 'FIN-066', 'No Tracking of Whether Runway Is Improving or Worsening Over Time', 'Financial Management', 'external', 'Even where runway gets recalculated occasionally, nobody tracks the trend — whether it is extending or shrinking, and at what pace. Without watching the trajectory, a runway that is quietly worsening month over month goes unnoticed until it is suddenly short, even though the warning signs were there in the trend all along.', '5', '8', '[]', '3', 'Runway Forecasting', '["FIN-006", "FIN-051", "FIN-056", "FIN-061"]', '2026-08-05 04:57:37.756089+00', '2026-08-05 05:01:19.978315+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('231', 'FIN-071', 'No Understanding of Which Costs Are Fixed vs Variable', 'Financial Management', 'external', 'The founder does not have a clear picture of which costs stay the same regardless of revenue (fixed) and which scale with sales volume (variable). Without this distinction, it is hard to know how profitability actually changes as the business grows, what the break-even point is, or which costs would shrink automatically if revenue dropped.', '5', '8', '[]', '3', 'P&L Literacy', '["FIN-011", "FIN-001", "FIN-016", "FIN-076", "FIN-081", "FIN-086"]', '2026-08-05 05:03:07.410674+00', '2026-08-05 05:14:48.817052+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('232', 'FIN-076', 'No Understanding of Why P&L Profit Doesn''t Equal Cash in the Bank', 'Financial Management', 'external', 'The founder does not understand why a business can show a profit on the P&L while still being low on cash, or vice versa — profit and cash are treated as the same thing. Without grasping the difference (unpaid invoices, non-cash items, timing gaps), decisions get made assuming a profitable P&L means healthy cash, leading to confusion or crisis when reality does not match the paper numbers.', '5', '8', '[]', '3', 'P&L Literacy', '["FIN-011", "FIN-001", "FIN-071", "FIN-081", "FIN-086"]', '2026-08-05 05:06:34.271386+00', '2026-08-05 05:14:48.817052+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('233', 'FIN-081', 'No Comparison of P&L Across Time Periods to Spot Trends', 'Financial Management', 'external', 'Even where a P&L is produced on a healthy cadence, each period gets reviewed in isolation rather than compared against previous months to see what is actually changing. Without this comparison, a slowly worsening margin, a creeping cost, or a positive trend all go unnoticed, because nobody is looking at the numbers side by side over time.', '5', '8', '[]', '3', 'P&L Literacy', '["FIN-011", "FIN-071", "FIN-076", "FIN-086"]', '2026-08-05 05:10:32.591441+00', '2026-08-05 05:14:48.817052+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('234', 'FIN-086', 'No Breakdown of P&L by Revenue Stream or Product Line', 'Financial Management', 'external', 'The P&L shows the business as one aggregated whole, without breaking profitability down by individual product, service, or revenue stream. This means a losing offering can hide inside an overall profitable P&L, subsidized invisibly by a stronger one, and the founder has no way to see which parts of the business are actually worth doubling down on versus cutting.', '5', '8', '[]', '3', 'P&L Literacy', '["FIN-011", "FIN-071", "FIN-076", "FIN-081"]', '2026-08-05 05:13:50.033525+00', '2026-08-05 05:15:28.738301+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('235', 'FIN-091', 'No Connection Between the Budget and Strategic Business Priorities', 'Financial Management', 'external', 'Even where a budget exists, its allocations do not reflect what the business is actually trying to prioritize that period. Spending stays roughly the same across categories from one period to the next, rather than deliberately shifting more budget toward strategic priorities and less toward lower-priority areas, so the budget does not actually help drive the business toward its goals.', '5', '8', '[]', '3', 'Budgeting', '["FIN-016", "FIN-011", "FIN-001", "FIN-096", "FIN-101", "FIN-106"]', '2026-08-05 05:23:37.234229+00', '2026-08-05 05:36:43.153453+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('236', 'FIN-096', 'No Revenue Assumptions Tied to the Budget', 'Financial Management', 'external', 'The budget is built around what the business wants to spend, without linking those spending commitments to a specific revenue assumption. Without this connection, the budget can quietly commit to more spending than the business can realistically afford if revenue comes in lower than hoped, and there is no way to know how sensitive the budget actually is to revenue landing as expected.', '5', '8', '[]', '3', 'Budgeting', '["FIN-016", "FIN-091", "FIN-001", "FIN-101", "FIN-106"]', '2026-08-05 05:27:11.970405+00', '2026-08-05 05:36:43.153453+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('237', 'FIN-101', 'No Involvement of Team or Department Heads in Building the Budget', 'Financial Management', 'external', 'The budget is built unilaterally by the founder, without input from the people who will actually be spending against it or who have visibility into what their area really needs. Without their involvement, budget numbers can be inaccurate, team members feel no ownership over staying within it, and the founder misses context that could have shaped a more realistic budget.', '5', '8', '[]', '3', 'Budgeting', '["FIN-016", "FIN-091", "FIN-096", "FIN-106"]', '2026-08-05 05:30:43.605628+00', '2026-08-05 05:36:43.153453+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('238', 'FIN-106', 'No Approval Process for Spending Outside the Budget', 'Financial Management', 'external', 'Once a budget is set, there is no defined process for what happens when someone wants to spend beyond what was allocated for a category. Unbudgeted purchases get made without any check or approval step, so the budget''s limits exist on paper but do not actually constrain real spending decisions as they come up, and overruns are usually only discovered after the fact.', '5', '8', '[]', '3', 'Budgeting', '["FIN-016", "FIN-091", "FIN-096", "FIN-101"]', '2026-08-05 05:35:45.904972+00', '2026-08-05 05:37:27.75339+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('239', 'FIN-111', 'No Follow-Through on Cutting Expenses Once Identified as Unnecessary', 'Financial Management', 'external', 'Even when an expense review identifies something as unnecessary or overpriced, the actual step of canceling, downgrading, or renegotiating it often does not happen. The finding gets noted but never acted on, so the same wasteful spend keeps showing up review after review without anything actually changing.', '5', '8', '[]', '3', 'Expense Review', '["FIN-021", "FIN-016", "FIN-001", "FIN-116", "FIN-121", "FIN-126"]', '2026-08-05 05:39:30.066083+00', '2026-08-05 06:57:47.241353+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('240', 'FIN-116', 'No Comparison of Vendor Pricing or Negotiation on Recurring Expenses', 'Financial Management', 'external', 'Even when a recurring expense is genuinely needed and gets used, nobody checks whether a cheaper alternative exists or attempts to negotiate better terms with the current vendor. Prices get accepted at face value and renewed automatically, so the business may be quietly overpaying for things it would keep anyway if it simply asked for a better deal.', '5', '8', '[]', '3', 'Expense Review', '["FIN-021", "FIN-111", "FIN-001", "FIN-121", "FIN-126"]', '2026-08-05 06:25:01.185065+00', '2026-08-05 06:57:47.241353+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('241', 'FIN-121', 'No Benchmark for Whether Expense Levels Are Reasonable', 'Financial Management', 'external', 'There is no external reference point for whether spending in a given category is normal, high, or low relative to revenue or similar businesses. Without any benchmark, the founder has no way to tell if an expense category is quietly out of line until it becomes a visible problem, and spending decisions get made based on gut feel rather than comparison to what is reasonable.', '5', '8', '[]', '3', 'Expense Review', '["FIN-021", "FIN-111", "FIN-116", "FIN-126"]', '2026-08-05 06:29:01.158887+00', '2026-08-05 06:57:47.241353+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('242', 'FIN-126', 'No Investigation Into What''s Actually Driving an Expense Category''s Increase', 'Financial Management', 'external', 'When a specific expense category grows quarter over quarter, nobody digs into what is actually causing the increase — a new tool, a price hike, unauthorized additions, or genuine usage growth. Without understanding the driver, the same increase keeps happening for the same unaddressed reason, and it is impossible to tell whether the growth is healthy or a sign of something going wrong.', '5', '8', '[]', '3', 'Expense Review', '["FIN-021", "FIN-111", "FIN-116", "FIN-121"]', '2026-08-05 06:56:54.84766+00', '2026-08-05 06:58:29.708848+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('243', 'FIN-131', 'No Verification That Financial Reports Are Actually Accurate', 'Financial Management', 'external', 'Financial reports get produced and even reviewed, but nobody checks whether the numbers in them are actually correct — reconciled against bank statements, invoices, or other source records. Without this verification step, errors, miscategorizations, or software glitches can persist for months, quietly undermining every decision made using those reports.', '5', '8', '[]', '3', 'Financial Reporting', '["FIN-026", "FIN-011", "FIN-001", "FIN-136", "FIN-141", "FIN-146", "FIN-151"]', '2026-08-05 07:00:28.149617+00', '2026-08-05 07:25:56.529222+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('244', 'FIN-136', 'No Sharing of Financial Reports With Co-Founders or Key Stakeholders', 'Financial Management', 'external', 'Even where financial reports are produced and reviewed, they stay with the founder and are never actually shared with co-founders, key team members, or the board. Without visibility into the numbers, other people making decisions for the business are doing so blind to the actual financial picture, and there is nothing simplified ready to share when someone does ask.', '5', '8', '[]', '3', 'Financial Reporting', '["FIN-026", "FIN-131", "FIN-011", "FIN-141"]', '2026-08-05 07:06:07.190739+00', '2026-08-05 07:10:50.472091+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('245', 'FIN-141', 'No Action Taken When Financial Reports Reveal a Problem', 'Financial Management', 'external', 'Even when a financial report clearly shows something concerning — a shrinking margin, an unexpected loss, an alarming trend — nothing happens as a result. The report gets reviewed, the concerning number gets acknowledged, but no decision, discussion, or corrective action actually follows, so the same problem persists into the next reporting period.', '5', '8', '[]', '3', 'Financial Reporting', '["FIN-026", "FIN-131", "FIN-136", "FIN-146", "FIN-151"]', '2026-08-05 07:09:47.603317+00', '2026-08-05 07:25:56.529222+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('246', 'FIN-146', 'No Financial Reports Prepared in a Format Ready for External Stakeholders', 'Financial Management', 'external', 'Internal financial reports might exist, but nothing is ever prepared in a format that could be shared with an external stakeholder — an investor, a lender, a potential acquirer — if the need arose. When that moment comes, the founder has to scramble to pull together something presentable from scratch rather than having anything ready to go, sometimes slowing down or complicating the opportunity itself.', '5', '8', '[]', '3', 'Financial Reporting', '["FIN-026", "FIN-131", "FIN-141", "FIN-151"]', '2026-08-05 07:21:18.558255+00', '2026-08-05 07:25:56.529222+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('247', 'FIN-151', 'No Synthesis of Multiple Financial Reports Into One Coherent Picture', 'Financial Management', 'external', 'Even where a P&L, balance sheet, and cash flow statement individually exist, nobody looks at them together to build a complete understanding of the business''s financial health. Each report gets reviewed in isolation, so the full story — a business that is profitable on paper but drowning in debt, or cash-tight despite strong margins — never gets seen because no one connects the dots across reports.', '5', '8', '[]', '3', 'Financial Reporting', '["FIN-026", "FIN-131", "FIN-141", "FIN-146"]', '2026-08-05 07:24:47.049009+00', '2026-08-06 03:52:36.682971+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('248', 'TM-035', 'No Access, Tools, or Accounts Set Up Before a New Hire''s First Day', 'Team & Leadership', 'external', 'A new hire arrives on day one without the logins, accounts, software access, or equipment they need to actually start working. Instead of a productive first day, time gets spent scrambling to set up email, tool access, and basic permissions — all things that could have been ready in advance if anyone had owned preparing for it.', '5', '8', '[]', '5', 'Early-Stage Onboarding', '["TM-025", "TM-004", "TM-030", "TM-041", "TM-046", "TM-051"]', '2026-08-06 03:54:43.38671+00', '2026-08-06 04:09:18.391898+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('249', 'TM-041', 'No Buddy or Point Person Assigned to Help a New Hire With Questions', 'Team & Leadership', 'external', 'A new hire has nobody specifically designated to go to with day-to-day questions. Instead of a clear point person, they either interrupt the busy founder repeatedly or sit on questions rather than ask, slowing down their ramp-up and making them feel unsupported during their first weeks.', '5', '8', '[]', '5', 'Early-Stage Onboarding', '["TM-025", "TM-035", "TM-030", "TM-046"]', '2026-08-06 03:57:54.196189+00', '2026-08-06 04:06:04.295371+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('250', 'TM-046', 'No Structured Training on How to Actually Perform the Role''s Core Tasks', 'Team & Leadership', 'external', 'Even where a first-week plan and documented expectations exist, there is no actual training process for the day-to-day skills, tools, or systems the new hire needs to do their job. They are expected to figure out how to perform core tasks by trial and error rather than being taught, which slows ramp-up and increases the risk of costly mistakes early on.', '5', '8', '[]', '5', 'Early-Stage Onboarding', '["TM-025", "TM-035", "TM-041", "TM-051", "TM-056"]', '2026-08-06 04:05:01.93756+00', '2026-08-06 04:16:53.971646+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('251', 'TM-051', 'No Introduction to Company Mission, Customers, or Business Context During Onboarding', 'Team & Leadership', 'external', 'A new hire learns their tasks, tools, and who to ask for help, but never gets introduced to the bigger picture — who the company''s customers actually are, why the business exists, or how their role fits into the larger mission. Without this context, the new hire can execute tasks correctly but struggles to make good judgment calls or feel genuinely connected to the work.', '5', '8', '[]', '5', 'Early-Stage Onboarding', '["TM-025", "TM-035", "TM-046"]', '2026-08-06 04:08:25.869854+00', '2026-08-06 04:13:54.815819+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('252', 'TM-056', 'No Recognition or Positive Reinforcement When a Team Member Performs Well', 'Team & Leadership', 'external', 'Performance management, where it happens at all, focuses entirely on catching problems — nothing exists to recognize or reinforce when someone is doing genuinely good work. Without positive feedback, early hires have no signal that what they are doing is valued, which can quietly erode motivation and make good performers wonder if their effort is even noticed.', '5', '8', '[]', '5', 'Early-Stage Performance Tracking', '["TM-030", "TM-025", "TM-046", "TM-061", "TM-066", "TM-071", "TM-076"]', '2026-08-06 04:16:01.654232+00', '2026-08-06 04:37:02.675593+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('253', 'TM-061', 'No Follow-Through After a Performance Conversation Happens', 'Team & Leadership', 'external', 'Even when a founder does have the difficult conversation about underperformance, nothing structured happens afterward — no improvement plan, no agreed-upon changes, no follow-up check to see if things actually got better. The conversation becomes a one-time event rather than the start of a process, so the same performance issue often resurfaces unchanged.', '5', '8', '[]', '5', 'Early-Stage Performance Tracking', '["TM-030", "TM-056", "TM-025", "TM-066"]', '2026-08-06 04:19:11.658251+00', '2026-08-06 04:26:01.627742+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('254', 'TM-066', 'No Two-Way Dialogue — Team Members Never Asked for Their Own Perspective on Performance', 'Team & Leadership', 'external', 'Performance conversations, where they happen, are entirely one-directional — the founder tells the employee how they are doing, but the employee is never asked how they think they are doing, what is going well for them, or what support they need. Without this two-way dialogue, the founder misses valuable perspective and the employee has no real voice in their own development.', '5', '8', '[]', '5', 'Early-Stage Performance Tracking', '["TM-030", "TM-056", "TM-061", "TM-071"]', '2026-08-06 04:25:07.517698+00', '2026-08-06 04:29:19.891241+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('255', 'TM-071', 'No Connection Between Individual Performance Tracking and Business Priorities', 'Team & Leadership', 'external', 'Even where performance gets discussed, what is tracked or evaluated is not tied to what the business actually needs most right now. People are assessed on vague, generic criteria rather than the specific outcomes that matter for the company''s current priorities, so performance conversations can feel disconnected from what would actually move the business forward.', '5', '8', '[]', '5', 'Early-Stage Performance Tracking', '["TM-030", "TM-056", "TM-066", "TM-076"]', '2026-08-06 04:28:20.79449+00', '2026-08-06 04:37:02.675593+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('256', 'TM-076', 'No Comparison of Performance Across Team Members to Identify Who Needs Support or Is Ready for More', 'Team & Leadership', 'external', 'Even where individual performance gets some attention, nobody steps back to compare people across the team — who is excelling and ready for more responsibility, who is struggling and needs support, or how the team''s overall performance is trending. Each person is assessed in isolation, so patterns that would only be visible by looking at everyone together go unnoticed.', '5', '8', '[]', '5', 'Early-Stage Performance Tracking', '["TM-030", "TM-056", "TM-071"]', '2026-08-06 04:36:08.966194+00', '2026-08-06 04:37:42.112952+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('257', 'OPS-031', 'No Central, Accessible Place Where SOPs Are Stored', 'Operations & Systems', 'external', 'Even where an SOP does get written, it ends up buried in an email, a random document, or a forgotten folder rather than a single, organized, easy-to-find location. Without a central repository, written procedures are effectively invisible — team members don''t know they exist, can''t find them when needed, and end up asking the founder directly anyway.', '5', '8', '[]', '4', 'SOP Creation', '["OPS-021", "OPS-001", "OPS-026", "OPS-036", "OPS-041", "OPS-046"]', '2026-08-06 04:40:02.504188+00', '2026-08-06 04:57:19.190858+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('258', 'OPS-036', 'No Verification That SOPs Are Actually Being Followed Once Written', 'Operations & Systems', 'external', 'Even where an SOP is written and stored somewhere findable, nobody checks whether people actually follow it. Team members can quietly do things their own way, deviate from the documented process, or ignore it entirely, and because there is no verification, the SOP becomes disconnected from what is actually happening day to day.', '5', '8', '[]', '4', 'SOP Creation', '["OPS-021", "OPS-031", "OPS-001", "OPS-041", "OPS-046"]', '2026-08-06 04:46:53.326554+00', '2026-08-06 04:57:19.190858+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('259', 'OPS-041', 'No Prioritization of Which Processes to Document First', 'Operations & Systems', 'external', 'When SOPs do get created, there is no clear criteria for deciding which processes to document first. Time gets spent writing up whatever comes to mind rather than the tasks that are most repeated, highest-risk, or most valuable to have written down, so critical processes can remain undocumented while less important ones get covered.', '5', '8', '[]', '4', 'SOP Creation', '["OPS-021", "OPS-031", "OPS-036", "OPS-046"]', '2026-08-06 04:50:30.739909+00', '2026-08-06 04:57:19.190858+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('260', 'OPS-046', 'No Way for Team Members to Suggest Improvements to Existing SOPs', 'Operations & Systems', 'external', 'SOPs are treated as one-directional — the founder writes them, and the team is expected to follow them, with no channel for the people actually doing the work to suggest changes or flag when something doesn''t work well in practice. Valuable improvements that team members notice while doing the task never make it back into the documented process, so the SOP stays frozen while the real work keeps evolving.', '5', '8', '[]', '4', 'SOP Creation', '["OPS-021", "OPS-031", "OPS-036", "OPS-041"]', '2026-08-06 04:56:05.525+00', '2026-08-06 04:58:37.291907+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('261', 'OPS-051', 'No Consistent Enforcement of Existing Policies', 'Operations & Systems', 'external', 'Even where a policy exists in writing, it does not get applied the same way to everyone. One person might be held strictly to a rule while another gets an exception, without any clear reason, which undermines trust in the policy and creates fairness and legal risk that often goes unnoticed until it becomes a real problem.', '5', '8', '[]', '4', 'Company Policies', '["OPS-026", "OPS-002", "TM-004", "OPS-056", "OPS-061", "OPS-066"]', '2026-08-06 05:00:46.591138+00', '2026-08-06 05:16:44.841254+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('262', 'OPS-056', 'No Process for Employees to Formally Acknowledge or Sign Off on Policies', 'Operations & Systems', 'external', 'Even where a policy document exists, there is no process for confirming that employees have actually read it and agreed to abide by it. Without a signed acknowledgment, the business has no record that a given policy was ever communicated to a specific person, creating both a practical gap — people may not know the policy exists — and a legal one, with no proof of notice if a dispute arises.', '5', '8', '[]', '4', 'Company Policies', '["OPS-026", "OPS-051", "TM-004", "OPS-061", "OPS-066"]', '2026-08-06 05:05:07.769345+00', '2026-08-06 05:16:44.841254+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('263', 'OPS-061', 'No Coverage of High-Risk Policy Areas Like Conduct, Harassment, or Data Privacy', 'Operations & Systems', 'external', 'Even where some basic policies exist, specific high-risk areas — workplace conduct, harassment, data privacy, conflicts of interest — often go completely uncovered. These are exactly the areas where a gap in written policy creates the most legal exposure and the most damage if something goes wrong, yet they are frequently the last thing an early-stage founder thinks to document.', '5', '9', '[]', '4', 'Company Policies', '["OPS-026", "OPS-051", "OPS-056", "OPS-066"]', '2026-08-06 05:10:05.649324+00', '2026-08-06 05:16:44.841254+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('264', 'OPS-066', 'No Process for Reviewing and Updating Policies as Laws or the Business Change', 'Operations & Systems', 'external', 'Even where policies exist, cover the right areas, and get enforced, nobody periodically checks whether they are still accurate as employment laws change or the business evolves. Policies get written once and left untouched, quietly becoming outdated or even non-compliant without anyone noticing until a problem forces a review.', '5', '8', '[]', '4', 'Company Policies', '["OPS-026", "OPS-051", "OPS-056", "OPS-061"]', '2026-08-06 05:15:50.092045+00', '2026-08-06 05:17:23.72782+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('265', 'SLX-172', 'No Structured Process for Generating New Leads', 'Sales Execution', 'external', 'The business has no consistent, deliberate process for generating new leads — leads arrive sporadically through personal network, word of mouth, or occasional outreach, rather than through a repeatable system. Without a structured lead-generation process, sales activity depends entirely on unpredictable inbound rather than a controllable, scalable input the founder can turn up when needed.', '5', '8', '[]', '3', 'Lead Generation', '["SLX-001", "SLX-006", "SLX-180", "SLX-185", "SLX-190", "SLX-195"]', '2026-08-06 07:41:51.078507+00', '2026-08-06 10:06:51.135766+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('266', 'SLX-180', 'No Outbound Prospecting Process to Proactively Reach New Potential Customers', 'Sales Execution', 'external', 'The business relies entirely on people coming to it — inbound interest, referrals, existing network — with no active outbound process for identifying and reaching out to potential customers who haven''t already shown interest. This caps growth at whatever inbound naturally provides, with no lever to proactively expand the pipeline.', '5', '8', '[]', '3', 'Lead Generation', '["SLX-172", "SLX-001", "SLX-006", "SLX-185", "SLX-190", "SLX-195"]', '2026-08-06 07:43:56.303493+00', '2026-08-06 10:06:51.202031+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('267', 'SLX-185', 'No Inbound Content or Presence Strategy to Attract Leads Organically', 'Sales Execution', 'external', 'The business has no deliberate content, SEO, or online presence strategy designed to attract potential customers organically. Without any inbound-generating asset working in the background, every lead requires active, ongoing effort rather than compounding over time through discoverability.', '5', '8', '[]', '3', 'Lead Generation', '["SLX-172", "SLX-180", "MEX-006", "SLX-190", "SLX-195"]', '2026-08-06 10:02:35.115684+00', '2026-08-06 10:06:51.266368+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('268', 'SLX-190', 'No Partnership or Co-Marketing Channel for Generating Leads', 'Sales Execution', 'external', 'The business has no relationships with complementary businesses, partners, or communities that could introduce new potential customers. Every lead comes from the business''s own direct efforts, with no channel leveraging someone else''s audience or trust to expand reach.', '5', '8', '[]', '3', 'Lead Generation', '["SLX-172", "SLX-180", "SLX-185", "SLX-195"]', '2026-08-06 10:03:33.116122+00', '2026-08-06 10:06:50.981935+00') on conflict do nothing;
insert into "problems" ("problem_id", "problem_code", "problem_name", "category", "layer", "description", "severity_min", "severity_max", "symptoms", "pillar_id", "subcategory", "related_problem_ids", "created_at", "updated_at") values ('269', 'SLX-195', 'No Paid Acquisition Channel Tested for Generating Leads', 'Sales Execution', 'external', 'Paid advertising or paid lead generation has never been tested as a channel, even in a small way. Every lead comes from free or organic effort, meaning growth is capped by how much manual work can be done, with no lever to pull for buying more volume when it''s actually needed.', '5', '8', '[]', '3', 'Lead Generation', '["SLX-172", "SLX-180", "SLX-185", "SLX-190"]', '2026-08-06 10:04:44.874488+00', '2026-08-06 10:06:51.055144+00') on conflict do nothing;
